            ["campaign.progressChapter"] = ("{0}/10", "{0}/10"),
            ["campaign.rareReward"] = ("{0} rare blueprints", "{0} bản thiết kế hiếm"),
            ["campaign.rewardFirst"] = ("Reward: {0} xu · {1} blueprints", "Thưởng: {0} xu · {1} bản thiết kế"),
            ["campaign.rewardReplay"] = ("Replay reward: {0} xu · {1} blueprints", "Thưởng chơi lại: {0} xu · {1} bản thiết kế"),
            ["campaign.side"] = ("Side mission", "Nhiệm vụ phụ"),
            ["campaign.sideAfter"] = ("Opens after mission {0}", "Mở sau nhiệm vụ {0}"),
            ["campaign.story.prologue"] = ("Two years ago, in one night, the private military corporation Hegemon seized the Lam Hai coast it had been paid to guard. Its director, Aurel, turned the ports, the oil fields and the highlands into a laboratory for weapons no army should own. The Coastal Alliance has rebuilt one brigade strong enough to go back: the 7th Mechanised, the Machine Brigade.", "Hai năm trước, chỉ trong một đêm, tập đoàn quân sự tư nhân Hegemon đã chiếm luôn dải duyên hải Lam Hải mà nó được thuê để canh giữ. Giám đốc Aurel biến bến cảng, mỏ dầu và vùng cao nguyên thành phòng thí nghiệm cho những thứ vũ khí không quân đội nào nên có. Liên minh Duyên hải đã dựng lại được một lữ đoàn đủ mạnh để quay về: Lữ đoàn Cơ giới 7, mà lính gọi là Lữ Đoàn Máy."),
            ["campaign.story.title"] = ("Machine Brigade: The Lam Hai Front", "Lữ Đoàn Cơ Giới: Mặt Trận Lam Hải"),
            ["chapter.1.summary"] = ("Dawn over Bãi Đổ Bộ. The landing craft ground on the sand under Hegemon's coastal guns, and the 7th Mechanised Brigade rolls ashore to open the first front in two years. Colonel Trần Khải has one order: get off the beach, find ground to build on, and take the Ashfield fortress before the enemy wakes up. Behind its walls waits the Bastion, an old walking fortress, still more than enough to stop a brigade that hesitates.", "Bình minh trên Bãi Đổ Bộ. Xuồng đổ bộ tì mũi lên cát dưới làn pháo bờ biển của Hegemon, và Lữ đoàn Cơ giới 7 lăn bánh lên bờ, mở mặt trận đầu tiên sau hai năm. Đại tá Trần Khải chỉ có một mệnh lệnh: rời bãi biển, tìm chỗ đứng chân, rồi chiếm pháo đài Đồng Tro trước khi địch kịp tỉnh. Sau những bức tường ấy là Bastion, một pháo đài biết đi đã cũ, nhưng vẫn thừa sức chặn một lữ đoàn biết chùn tay."),
            ["chapter.1.title"] = ("Coast of Fire", "Bờ biển lửa"),
            ["chapter.2.summary"] = ("Every Hegemon engine runs on the oil of Dunebreak and Red Rock. Cut it, and the machines starve. The enemy knows it too: General Varga, the man who built the Behemoth, has come south in person to guard his fuel. Ahead lie the pipelines, the wells, the refinery, and whatever monster Varga has parked inside it.", "Mọi cỗ máy của Hegemon đều chạy bằng dầu của Đồi Cát và Hẻm Đá Đỏ. Cắt nguồn dầu, lũ máy sẽ chết đói. Địch cũng biết điều đó: tướng Varga, cha đẻ của Behemoth, đích thân xuống phía nam giữ kho nhiên liệu. Phía trước là đường ống, giếng dầu, nhà máy lọc dầu, và con quái vật nào đó Varga đang giấu bên trong."),
            ["chapter.2.title"] = ("Black Gold", "Vàng đen"),
            ["chapter.3.summary"] = ("Winter comes early to the highlands. Across Frostpeak and the Whiteout pass, Colonel Orlov has built a radar line that sees every convoy, and guns that answer within a minute. His Iron Bird, a gunship the size of a ship, hunts anything that moves on the snow. The brigade has anti-air now. It will need every launcher to break the line and reach the Ice Fortress behind it.", "Mùa đông về sớm trên cao nguyên. Dọc Đỉnh Sương Giá và Đèo Bão Tuyết, đại tá Orlov dựng một tuyến radar thấy được mọi đoàn xe, cùng những khẩu pháo khai hỏa chưa tới một phút sau. Chim Sắt của hắn, một pháo hạm bay to như con tàu, săn mọi thứ nhúc nhích trên tuyết. Lữ đoàn giờ đã có phòng không. Sẽ cần đến từng bệ phóng để phá tuyến radar và tới được Pháo Đài Băng phía sau."),
            ["chapter.3.title"] = ("The Long Winter", "Mùa đông dài"),
            ["chapter.4.summary"] = ("Everything Hegemon builds leaves through Ironport. Admiral Kessler runs its cranes, its rails and its armoured trains to a timetable nobody has ever seen broken. The Alliance goes over to the attack: take the Rust Yard, cut the rail lines, and seize the port itself. On the docks, Linh's intercepts keep mentioning one word: Tempest.", "Mọi thứ Hegemon chế tạo đều đi qua Cảng Thép. Đô đốc Kessler điều hành cần cẩu, đường ray và những đoàn tàu bọc thép theo một thời gian biểu chưa ai thấy trễ bao giờ. Liên minh chuyển sang phản công: chiếm Bãi Sắt Gỉ, cắt đường ray, rồi đánh chiếm chính bến cảng. Trên cầu tàu, các bản chặn thu của Linh cứ nhắc mãi một cái tên: Tempest."),
            ["chapter.4.title"] = ("Steel Harbour", "Cảng thép"),
            ["chapter.5.summary"] = ("Under the volcanoes of Ember Ridge and the canopy of the Jungle Pass, Dr Sen builds drones by the thousand. Her masterpiece, the Hive, can blacken the sky over a whole division; its mothership carries the swarm wherever Hegemon points it. Burn the drone works and the sky clears. But Linh has noticed something odd: Sen's own messages are getting shorter, and angrier.", "Dưới chân núi lửa Sườn Dung Nham và tán rừng Đèo Rừng Rậm, tiến sĩ Sen chế tạo drone theo từng nghìn chiếc. Kiệt tác của bà, Tổ Ong, có thể che đen bầu trời trên cả một sư đoàn; tàu mẹ của nó chở bầy drone tới bất cứ đâu Hegemon chỉ tay. Đốt xưởng drone thì bầu trời sẽ sạch. Nhưng Linh để ý một điều lạ: các bức điện của chính Sen cứ ngắn dần, và gay gắt dần."),
            ["chapter.5.title"] = ("Jungle Fire", "Lửa rừng"),
            ["chapter.6.summary"] = ("Hegemon strikes back. Varga throws everything left at the ground the brigade took in the first act: Ashfield, the Whiteout pass, and the Hydro Dam that lights half the coast. Engineer Mai has done the impossible and got a captured Behemoth running for our side. Varga has done something worse: his new Behemoth, the Frost Monster, is heading for the dam, and General Hùng's relief army is days away.", "Hegemon phản đòn. Varga ném tất cả những gì còn lại vào những vùng đất lữ đoàn đã chiếm ở hồi đầu: Đồng Tro, Đèo Bão Tuyết, và Đập Thủy Điện thắp sáng nửa dải duyên hải. Kỹ sư Mai đã làm được điều không tưởng: cho một chiếc Behemoth bắt được chạy về phía ta. Varga làm được điều tệ hơn: Behemoth mới của hắn, Quái Vật Băng, đang tiến về con đập, trong khi đạo quân cứu viện của tướng Hùng còn cách nhiều ngày đường."),
            ["chapter.6.title"] = ("Counterstrike", "Tổng phản công"),
            ["chapter.7.summary"] = ("Sen's files are clear: Silver Bug is real, it flies, and Aurel means to hang it over the capital. Between the brigade and the sky stands Quạ Đen, Black Crow, Hegemon's best pilot and Diều Hâu's old wingman. Take Skyhold, the air base he flies from, and the sky over the coast belongs to the Alliance.", "Hồ sơ của Sen đã rõ: Bọ Bạc có thật, nó bay được, và Aurel định treo nó trên bầu trời thủ đô. Giữa lữ đoàn và bầu trời là Quạ Đen, phi công giỏi nhất của Hegemon và là đồng đội cũ của Diều Hâu. Chiếm Tầng Mây, căn cứ không quân nơi hắn cất cánh, là bầu trời duyên hải thuộc về Liên minh."),
            ["chapter.7.title"] = ("War in the Air", "Chiến tranh trên không"),
            ["chapter.8.summary"] = ("The road runs through Metro City to Lam Thành, the capital, where Aurel sits in the old government quarter. General Hùng brings his army to join the liberation, with his own base and his own ideas about who should rule afterwards. Somewhere under the city, the Doomsday Train is moving.", "Con đường chạy qua Đô Thành tới Lam Thành, thủ đô, nơi Aurel ngự trong khu chính phủ cũ. Tướng Hùng kéo quân tới cùng giải phóng, với căn cứ riêng của ông, và những ý nghĩ riêng về chuyện ai sẽ cầm quyền sau đó. Đâu đó dưới lòng thành phố, Đoàn Tàu Tận Thế đang lăn bánh."),
            ["chapter.8.title"] = ("The Capital", "Thủ đô"),
            ["chapter.9.summary"] = ("Everything Hegemon has left is at the Silver Bug launch site in the southern desert: every general still standing, every gun, and the Bug itself, being finished on its pad. One by one the generals come out to meet the brigade. One by one they have to be beaten. At the end of the road Aurel waits, and Silver Bug in its complete form.", "Tất cả những gì Hegemon còn lại đều dồn về bãi phóng Bọ Bạc giữa sa mạc phía nam: mọi viên tướng còn đứng vững, mọi khẩu pháo, và chính Bọ Bạc đang được hoàn thiện trên bệ phóng. Từng viên tướng một ra nghênh chiến lữ đoàn. Từng người một phải bị đánh bại. Ở cuối con đường, Aurel đang chờ, cùng Bọ Bạc trong hình dạng hoàn chỉnh."),
            ["chapter.9.title"] = ("The Launch Site", "Bãi phóng"),
            ["char.aurel.bio"] = ("Aurel talks about war the way accountants talk about quarterly results. He took the coast because the contract allowed it, and he built Silver Bug because nobody could stop him. He commands the best of everything, and he plans to never be in range of any of it.", "Aurel nói về chiến tranh như kế toán nói về báo cáo quý. Hắn chiếm dải duyên hải vì hợp đồng cho phép, và chế tạo Bọ Bạc vì chẳng ai ngăn nổi. Hắn chỉ huy những thứ tốt nhất của mọi loại, và định sẽ không bao giờ đứng trong tầm bắn của thứ nào."),
            ["char.aurel.name"] = ("Director Aurel", "Giám đốc Aurel"),
            ["char.aurel.role"] = ("Head of Hegemon; Project Silver Bug", "Người đứng đầu Hegemon; dự án Bọ Bạc"),
            ["char.dieuhau.bio"] = ("Captain Lê Phong, call sign Diều Hâu (Hawk), flies everything the brigade owns that leaves the ground. Loud, cheerful, better than he admits. He trained at the same school as Quạ Đen, and they were wingmen, once.", "Đại úy Lê Phong, tên gọi Diều Hâu, lái mọi thứ biết cất cánh của lữ đoàn. Ồn ào, vui tính, và giỏi hơn những gì anh chịu nhận. Anh học cùng trường bay với Quạ Đen, và đã từng là đồng đội bay kèm của hắn."),
            ["char.dieuhau.name"] = ("Diều Hâu", "Diều Hâu"),
            ["char.dieuhau.role"] = ("Pilot; leads the air wing", "Phi công, chỉ huy phi đội"),
            ["char.hq.name"] = ("Brigade HQ", "Sở chỉ huy Lữ đoàn"),
            ["char.hq.role"] = ("Radio", "Bộ đàm"),
            ["char.hung.bio"] = ("Hùng commands the Alliance's largest army and never lets anyone forget it. Brave, generous with his men, hungry for the one thing a liberator can take: the city he frees. He fights beside the brigade in the great operations, with a base of his own.", "Hùng chỉ huy đạo quân lớn nhất của Liên minh và không bao giờ để ai quên điều đó. Dũng cảm, hào phóng với lính của mình, và thèm khát đúng một thứ mà người giải phóng có thể lấy: thành phố ông giải phóng. Ông sát cánh cùng lữ đoàn trong các chiến dịch lớn, với căn cứ riêng."),
            ["char.hung.name"] = ("General Hùng", "Tướng Hùng"),
            ["char.hung.role"] = ("Commander, Alliance Northern Army", "Tư lệnh Tập đoàn quân Phương Bắc của Liên minh"),
            ["char.kessler.bio"] = ("Kessler has never lost a shipment, a train or an argument about a timetable. He runs Hegemon's ports and rail lines, and armours both. His armies are balanced to the gram, his bases a little of everything, and he mines anything he cannot hold.", "Kessler chưa từng để thất lạc một chuyến hàng, một đoàn tàu hay thua một cuộc cãi về thời gian biểu. Hắn điều hành bến cảng và đường sắt của Hegemon, và bọc thép cả hai. Quân của hắn cân bằng đến từng gam, căn cứ của hắn thứ gì cũng có một ít, và hắn rải mìn bất cứ chỗ nào không giữ nổi."),
            ["char.kessler.name"] = ("Admiral Kessler", "Đô đốc Kessler"),
            ["char.kessler.role"] = ("Hegemon logistics, ports and trains", "Hậu cần, bến cảng và đường sắt của Hegemon"),
            ["char.khai.bio"] = ("Fifty-two, calm, practical, never heard to raise his voice on the radio. Khải lost his home town on the Night of Steel and does not talk about it. He plans battles like a mechanic fixes an engine: find what is broken, fix that, move on.", "Năm mươi hai tuổi, điềm tĩnh, thực tế, chưa ai nghe ông lớn tiếng trên sóng bộ đàm. Khải mất quê nhà trong Đêm Thép và không bao giờ nhắc tới. Ông lên kế hoạch trận đánh như thợ máy sửa động cơ: tìm chỗ hỏng, sửa chỗ đó, rồi đi tiếp."),
            ["char.khai.name"] = ("Colonel Trần Khải", "Đại tá Trần Khải"),
            ["char.khai.role"] = ("Commander, 7th Mechanised Brigade", "Chỉ huy Lữ đoàn Cơ giới 7"),
            ["char.linh.bio"] = ("Linh reads Hegemon's mail. Intercepts, captured drives, a burnt notebook: she turns them into targets, and into the side jobs nobody else has time for. Precise, patient, and the only one who can make Colonel Khải laugh.", "Linh đọc thư của Hegemon. Bản chặn thu, ổ cứng thu được, một cuốn sổ cháy dở: cô biến tất cả thành mục tiêu, và thành những nhiệm vụ phụ không ai có thời gian làm. Chính xác, kiên nhẫn, và là người duy nhất làm được đại tá Khải bật cười."),
            ["char.linh.name"] = ("Lieutenant Linh", "Trung úy Linh"),
            ["char.linh.role"] = ("Intelligence officer", "Sĩ quan tình báo"),
            ["char.mai.bio"] = ("Mai keeps the brigade's base running and signs off every HQ upgrade. For three years she welded Behemoth hulls for Hegemon as a contract engineer, until she understood what they were for and walked out. She knows every weak seam in Varga's machines, and she has not forgiven herself for any of them.", "Mai giữ cho căn cứ của lữ đoàn vận hành và là người ký duyệt mọi lần nâng cấp sở chỉ huy. Suốt ba năm, cô hàn vỏ Behemoth cho Hegemon theo hợp đồng, cho đến khi hiểu chúng được làm ra để làm gì và bỏ đi. Cô biết từng đường hàn yếu trên những cỗ máy của Varga, và chưa tha thứ cho mình vì bất cứ đường nào."),
            ["char.mai.name"] = ("Engineer Mai", "Kỹ sư Mai"),
            ["char.mai.role"] = ("Chief engineer; runs the base", "Kỹ sư trưởng, phụ trách căn cứ"),
            ["char.orlov.bio"] = ("Orlov has never seen the face of a man he killed, and prefers it that way. He fights from thirty kilometres off, with radar, rockets and patience. His bases are gun lines; his armies screen his batteries and wait for the shells to do the work.", "Orlov chưa từng nhìn mặt người nào hắn giết, và hắn muốn thế. Hắn đánh từ cách xa ba mươi cây số, bằng radar, rốc-két và sự kiên nhẫn. Căn cứ của hắn là những trận địa pháo; quân của hắn che chắn cho các khẩu đội và chờ đạn pháo làm nốt phần việc."),
            ["char.orlov.name"] = ("Colonel Orlov", "Đại tá Orlov"),
            ["char.orlov.role"] = ("Hegemon artillery", "Pháo binh Hegemon"),
            ["char.quaden.bio"] = ("Nobody uses his real name. Black Crow commands Hegemon's air wing from Skyhold and has more kills than the rest of it together. He flies gunships, jets and drones in one screaming wave, and his bases are ringed with missiles. He and Diều Hâu have unfinished business.", "Không ai gọi tên thật của hắn. Quạ Đen chỉ huy lực lượng không quân Hegemon từ Tầng Mây và có số lần hạ địch nhiều hơn cả phần còn lại cộng lại. Hắn tung trực thăng, phản lực và drone thành một đợt gào thét, và căn cứ của hắn vây kín tên lửa. Giữa hắn và Diều Hâu còn một món nợ chưa trả."),
            ["char.quaden.name"] = ("Quạ Đen", "Quạ Đen"),
            ["char.quaden.role"] = ("Hegemon air force ace", "Át chủ bài không quân Hegemon"),
            ["char.sen.bio"] = ("Sen builds swarms the way other people knit. The Hive was meant to be a rescue system for disaster zones; Hegemon armed it before she finished her coffee. She fights with drones, jammers and hangars full of both, and she has begun to wonder who she is working for.", "Sen tạo ra bầy drone như người khác đan len. Tổ Ong vốn được thiết kế làm hệ thống cứu hộ cho vùng thảm họa; Hegemon vũ trang cho nó trước khi bà kịp uống xong ly cà phê. Bà đánh bằng drone, xe gây nhiễu và những nhà chứa đầy cả hai thứ, và bà bắt đầu tự hỏi mình đang làm việc cho ai."),
            ["char.sen.name"] = ("Dr Sen", "Tiến sĩ Sen"),
            ["char.sen.role"] = ("Hegemon drones; creator of the Hive", "Drone của Hegemon; người tạo ra Tổ Ong"),
            ["char.varga.bio"] = ("Varga believes weight wins wars. He designed the Behemoth on a napkin and spent a nation's budget building it. Brave, stubborn, loyal to his machines more than to Aurel. His armies are all tanks and tank killers; his bases bristle with anti-tank guns.", "Varga tin rằng sức nặng thắng được chiến tranh. Hắn vẽ Behemoth trên một tờ giấy ăn rồi tiêu ngân sách của cả một quốc gia để chế tạo nó. Gan lì, cứng đầu, trung thành với những cỗ máy của mình hơn là với Aurel. Quân của hắn toàn xe tăng và xe diệt tăng; căn cứ của hắn dựng đầy pháo chống tăng."),
            ["char.varga.name"] = ("General Varga", "Tướng Varga"),
            ["char.varga.role"] = ("Hegemon armour; father of the Behemoth", "Thiết giáp Hegemon; cha đẻ của Behemoth"),
            ["choice.c1m10.dump"] = ("Blow the ammunition dumps", "Cho nổ kho đạn"),
            ["choice.c1m10.dump.info"] = ("The garrison earns 30 % less for the rest of the battle.", "Quân địch kiếm được ít hơn 30 % trong suốt phần còn lại của trận."),
            ["choice.c1m10.radar"] = ("Knock out the radar", "Phá trạm radar"),
            ["choice.c1m10.radar.info"] = ("Diều Hâu can reach the fortress: a free airstrike about every minute.", "Diều Hâu bay tới được pháo đài: một đợt không kích miễn phí khoảng mỗi phút."),
            ["choice.c2m10.oasis"] = ("Hold the oasis radio", "Giữ đài phát ốc đảo"),
            ["choice.c2m10.oasis.info"] = ("Hold it 90 s: Diều Hâu's airstrikes, free, about every minute.", "Giữ 90 giây: không kích miễn phí của Diều Hâu, khoảng mỗi phút một lượt."),
            ["choice.c2m10.tanks"] = ("Burn the fuel tanks", "Đốt bồn nhiên liệu"),
            ["choice.c2m10.tanks.info"] = ("Varga's army earns 30 % less for the rest of the battle.", "Quân Varga kiếm được ít hơn 30 % trong suốt phần còn lại của trận."),
            ["choice.c3m10.depots"] = ("Blow the fuel depots", "Cho nổ kho nhiên liệu"),
            ["choice.c3m10.depots.info"] = ("Orlov's army earns 30 % less for the rest of the battle.", "Quân Orlov kiếm được ít hơn 30 % trong suốt phần còn lại của trận."),
            ["choice.c3m10.radars"] = ("Destroy the fortress radars", "Phá radar của pháo đài"),
            ["choice.c3m10.radars.info"] = ("Free airstrikes about every 50 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 50 giây trong suốt phần còn lại của trận."),
            ["choice.c4m10.crane"] = ("Burn the fuel wagons", "Đốt các toa nhiên liệu"),
            ["choice.c4m10.crane.info"] = ("Kessler earns 30 % less for the rest of the battle.", "Kessler kiếm được ít hơn 30 % trong suốt phần còn lại của trận."),
            ["choice.c4m10.signal"] = ("Hold the signal box (150 s)", "Giữ trạm tín hiệu (150 giây)"),
            ["choice.c4m10.signal.info"] = ("Free airstrikes about every 55 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 55 giây trong suốt phần còn lại của trận."),
            ["choice.c5m10.fuel"] = ("Burn the drone fuel", "Đốt nhiên liệu drone"),
            ["choice.c5m10.fuel.info"] = ("Sen's army earns 30 % less for the rest of the battle.", "Quân của Sen kiếm được ít hơn 30 % trong suốt phần còn lại của trận."),
            ["choice.c5m10.relay"] = ("Hold the relay (120 s)", "Giữ trạm tiếp sóng (120 giây)"),
            ["choice.c5m10.relay.info"] = ("Free airstrikes about every 55 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 55 giây trong suốt phần còn lại của trận."),
            ["choice.c6m10.spillway"] = ("Burn Varga's depot at the ford", "Đốt kho của Varga ở bến lội"),
            ["choice.c6m10.spillway.info"] = ("Varga earns 30 % less for the rest of the battle.", "Varga kiếm được ít hơn 30 % trong suốt phần còn lại của trận."),
            ["choice.c6m10.station"] = ("Hold the power station (150 s)", "Giữ trạm phát điện (150 giây)"),
            ["choice.c6m10.station.info"] = ("Free airstrikes about every 55 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 55 giây trong suốt phần còn lại của trận."),
            ["choice.c7m10.fuel"] = ("Burn the fuel park", "Đốt bãi nhiên liệu"),
            ["choice.c7m10.fuel.info"] = ("Quạ Đen earns 30 % less for the rest of the battle.", "Quạ Đen kiếm được ít hơn 30 % trong suốt phần còn lại của trận."),
            ["choice.c7m10.tower"] = ("Destroy the control tower and radome", "Phá tháp điều khiển và vòm radar"),
            ["choice.c7m10.tower.info"] = ("Free airstrikes about every 50 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 50 giây trong suốt phần còn lại của trận."),
            ["choice.c8m10.gardens"] = ("Hold the gardens (150 s)", "Giữ khu vườn (150 giây)"),
            ["choice.c8m10.gardens.info"] = ("Free airstrikes about every 55 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 55 giây trong suốt phần còn lại của trận."),
            ["choice.c8m10.ministry"] = ("Burn the supply ministry", "Đốt Bộ Hậu cần"),
            ["choice.c8m10.ministry.info"] = ("Aurel's guard earns 30 % less for the rest of the battle.", "Vệ binh của Aurel kiếm được ít hơn 30 % trong suốt phần còn lại của trận."),
            ["choice.c9m10.propellant"] = ("Burn the propellant tanks", "Đốt các bồn nhiên liệu đẩy"),
            ["choice.c9m10.propellant.info"] = ("Aurel earns 30 % less for the rest of the battle.", "Aurel kiếm được ít hơn 30 % trong suốt phần còn lại của trận."),
            ["choice.c9m10.radars"] = ("Destroy the west radars", "Phá radar phía tây"),
            ["choice.c9m10.radars.info"] = ("Free airstrikes about every 50 s for the rest of the battle.", "Không kích miễn phí khoảng mỗi 50 giây trong suốt phần còn lại của trận."),
            ["dossier.before"] = ("Before the landing", "Trước cuộc đổ bộ"),
            ["dossier.bosses"] = ("Boss files", "Hồ sơ trùm"),
            ["dossier.chapterFiles"] = ("Chapter {0}", "Chương {0}"),
            ["dossier.empty"] = ("Every mission won adds a file here.", "Mỗi nhiệm vụ giành thắng lợi sẽ thêm một tư liệu vào đây."),
            ["dossier.files"] = ("Story files", "Tư liệu"),
            ["dossier.locked"] = ("Not met yet.", "Chưa gặp mặt."),
            ["dossier.lockedBoss"] = ("Beat it to open its file.", "Hạ gục nó để mở hồ sơ."),
            ["dossier.lockedChapter"] = ("Not yet written.", "Chưa được viết nên."),
            ["dossier.people"] = ("People", "Nhân vật"),
            ["dossier.timeline"] = ("Timeline", "Dòng thời gian"),
            ["goal.duel"] = ("Destroy the general's HQ", "Phá sở chỉ huy của tướng địch"),
            ["goal.evacuate"] = ("Evacuate", "Sơ tán"),
            ["goal.outpost"] = ("Set up an outpost", "Lập tiền đồn"),
            ["goal.relieve"] = ("Break the siege", "Giải vây"),
            ["mission.c1m01.brief"] = ("The landing craft are on the sand. Take the beach and the draw above it before Hegemon's garrison wakes up. Your army fights on its own: you choose where it goes, what it brings and when the guns fire.", "Xuồng đổ bộ đã chạm cát. Chiếm bãi biển và con dốc phía trên trước khi đồn Hegemon kịp tỉnh ngủ. Quân ta tự chiến đấu: bạn chọn nơi đánh, mang theo gì và lúc nào pháo khai hỏa."),
            ["mission.c1m01.fragment"] = ("Brigade log, day one: 212 vehicles ashore by 06:40. Losses light. The coastal guns fired late and badly; somebody in Hegemon did not believe we would come.", "Nhật ký lữ đoàn, ngày thứ nhất: 212 xe lên bờ trước 06:40. Thiệt hại nhẹ. Pháo bờ biển bắn muộn và bắn tồi; có kẻ nào đó bên Hegemon đã không tin chúng ta dám tới."),
            ["mission.c1m01.fragment.title"] = ("The first boot on the sand", "Dấu giày đầu tiên trên cát"),
            ["mission.c1m01.name"] = ("Landfall", "Đổ bộ"),
            ["mission.c1m02.brief"] = ("A radar on the bluffs is calling Hegemon's guns onto every landing craft still in the bay. Knock it down, and the boats behind us can come in unseen.", "Trạm radar trên vách đá đang gọi pháo Hegemon bắn vào từng chiếc xuồng còn trong vịnh. Hạ nó xuống, các đợt đổ bộ sau sẽ vào bờ mà không bị phát hiện."),
            ["mission.c1m02.fragment"] = ("Recovered from the radar's log: \"Contacts multiplying. Request confirmation from Director's office. Request confirmation. Request—\" Nobody confirmed.", "Trích từ sổ trực của trạm radar: \"Mục tiêu tăng lên liên tục. Đề nghị văn phòng Giám đốc xác nhận. Đề nghị xác nhận. Đề nghị—\" Không ai xác nhận cả."),
            ["mission.c1m02.fragment.title"] = ("A coastal radar's last report", "Bản tin cuối của trạm radar"),
            ["mission.c1m02.name"] = ("Blind the Coast", "Bịt mắt bờ biển"),
            ["mission.c1m03.brief"] = ("Greenvale's crossroads village and its two farms command every road inland. A handful of scouts hold them. Take all three and the brigade has room to breathe.", "Làng ngã tư ở Lũng Xanh cùng hai trang trại kiểm soát mọi con đường vào nội địa. Chỉ vài xe trinh sát canh giữ. Chiếm cả ba, lữ đoàn sẽ có đất mà thở."),
            ["mission.c1m03.fragment"] = ("The farmers of Greenvale kept planting for two years under the Protectorate. When our tanks came up the road, an old man offered Colonel Khải a bag of rice and asked if we were staying.", "Nông dân Lũng Xanh vẫn cày cấy suốt hai năm dưới thời \"Bảo hộ\". Khi xe tăng ta lên đường làng, một cụ già đưa đại tá Khải một bao gạo và hỏi quân mình có ở lại không."),
            ["mission.c1m03.fragment.title"] = ("Greenvale's farmers", "Nông dân Lũng Xanh"),
            ["mission.c1m03.name"] = ("The Crossroads", "Ngã tư Lũng Xanh"),
            ["mission.c1m04.brief"] = ("Mai wants the crossroads for a base. Take it, set up an outpost there, and keep it standing while her crews fly the towers in. Once it holds, the brigade has its first HQ on the coast.", "Mai muốn lấy ngã tư làm căn cứ. Chiếm nó, lập tiền đồn ở đó và giữ vững trong lúc đội của cô thả tháp xuống. Trụ được rồi, lữ đoàn sẽ có sở chỉ huy đầu tiên trên dải duyên hải."),
            ["mission.c1m04.fragment"] = ("Pinned to the first HQ's door: \"Generators (4). Welding rods (all of them). Coffee (more than that). Do not touch the blue crates. — M.\"", "Dán trên cửa sở chỉ huy đầu tiên: \"Máy phát điện (4). Que hàn (tất cả chỗ có). Cà phê (nhiều hơn thế). Không được đụng vào thùng màu xanh. — M.\""),
            ["mission.c1m04.fragment.title"] = ("Mai's shopping list", "Danh sách mua sắm của Mai"),
            ["mission.c1m04.name"] = ("First Outpost", "Tiền đồn đầu tiên"),
            ["mission.c1m05.brief"] = ("Hegemon is landing behind us: a hovercraft is coming up the beach at night with a company of armour aboard. Destroy it before it can unload, or the beachhead is cut off.", "Hegemon đang đổ bộ sau lưng ta: một tàu đệm khí chở cả đại đội thiết giáp đang lao lên bãi biển trong đêm. Tiêu diệt nó trước khi nó kịp dỡ quân, nếu không đầu cầu sẽ bị cắt đứt."),
            ["mission.c1m05.fragment"] = ("Hegemon order, captured: \"Retake the beach by morning. Use the hovercraft. Do not use the word 'counterattack' in reports to the Director.\"", "Mệnh lệnh Hegemon thu được: \"Chiếm lại bãi biển trước sáng mai. Dùng tàu đệm khí. Không dùng từ 'phản công' trong báo cáo gửi Giám đốc.\""),
            ["mission.c1m05.fragment.title"] = ("Counter-landing", "Phản đổ bộ"),
            ["mission.c1m05.name"] = ("Iron Tide", "Thủy triều thép"),
            ["mission.c1m06.brief"] = ("Fuel and shells for the forward units, five trucks in the rain. Get at least three to the west farm. The trucks wait for an escort; they will not drive into an ambush alone.", "Nhiên liệu và đạn cho các đơn vị tiền phương, năm xe tải dưới mưa. Đưa ít nhất ba xe tới trang trại phía tây. Xe tải sẽ chờ hộ tống; chúng không tự lao vào ổ phục kích đâu."),
            ["mission.c1m06.fragment"] = ("Driver's note found in a cab: \"Rain for three days. The mud is on our side for once: their raiders bog down before they reach us.\"", "Mẩu giấy của tài xế tìm thấy trong ca-bin: \"Mưa ba ngày rồi. Lần này bùn đứng về phía ta: bọn đột kích sa lầy trước khi tới được chỗ mình.\""),
            ["mission.c1m06.fragment.title"] = ("Rain", "Mưa"),
            ["mission.c1m06.name"] = ("Supply Line", "Đường tiếp tế"),
            ["mission.c1m07.brief"] = ("Hegemon wants the grain silos and the water tower at Greenvale's south end burned, so the valley starves and blames us. Keep at least one standing through the storm.", "Hegemon muốn đốt các kho lúa và tháp nước ở phía nam Lũng Xanh, để thung lũng đói và đổ lỗi cho ta. Giữ ít nhất một công trình đứng vững qua cơn bão."),
            ["mission.c1m07.fragment"] = ("Hegemon field order: \"Deny the valley's food to the enemy.\" Linh underlined \"the enemy\" twice. The valley's food feeds the valley.", "Lệnh dã chiến của Hegemon: \"Không để lương thực của thung lũng rơi vào tay địch.\" Linh gạch chân chữ \"địch\" hai lần. Lương thực của thung lũng là để nuôi chính thung lũng."),
            ["mission.c1m07.fragment.title"] = ("Scorched earth", "Tiêu thổ"),
            ["mission.c1m07.name"] = ("Harvest Guard", "Giữ mùa gặt"),
            ["mission.c1m08.brief"] = ("Ashfield's town and its two fuel depots lie in front of the fortress. Take all three, and the fortress is cut off from the road.", "Thị trấn Đồng Tro cùng hai kho nhiên liệu nằm ngay trước pháo đài. Chiếm cả ba, pháo đài sẽ bị cắt khỏi đường cái."),
            ["mission.c1m08.fragment"] = ("Before the Night of Steel, Ashfield made bricks. The fortress on the hill was a brickworks; Hegemon kept the kilns and put guns in them.", "Trước Đêm Thép, Đồng Tro làm gạch. Pháo đài trên đồi vốn là lò gạch; Hegemon giữ lại các lò nung rồi đặt pháo vào trong đó."),
            ["mission.c1m08.fragment.title"] = ("Ashfield", "Đồng Tro"),
            ["mission.c1m08.name"] = ("Ashfield Road", "Đường vào Đồng Tro"),
            ["mission.c1m09.brief"] = ("The guns for the fortress need shells. Bring the ammunition trucks round the east road into Ashfield town; three of five must get there.", "Pháo đánh pháo đài cần đạn. Đưa đoàn xe chở đạn vòng đường phía đông vào thị trấn Đồng Tro; năm xe phải tới được ba."),
            ["mission.c1m09.fragment"] = ("Artillery officer's estimate for the fortress: \"Four thousand rounds, or one engineer who knows where the kilns are weakest.\" Mai volunteered. Khai ordered the rounds.", "Ước tính của sĩ quan pháo binh cho pháo đài: \"Bốn nghìn quả đạn, hoặc một kỹ sư biết lò nung nào yếu nhất.\" Mai xung phong. Khải vẫn cho chở đạn."),
            ["mission.c1m09.fragment.title"] = ("Shell count", "Đếm đạn"),
            ["mission.c1m09.name"] = ("Ammunition for the Siege", "Đạn cho trận vây thành"),
            ["mission.c1m10.brief"] = ("The old brickworks on the hill is Hegemon's strongest point on the coast, and the Bastion walks its yard. Burn the fuel depot outside, choose how to soften the walls, bring the Bastion down and level the command HQ.", "Lò gạch cũ trên đồi là điểm mạnh nhất của Hegemon trên dải duyên hải, và Bastion đi tuần trong sân của nó. Đốt kho nhiên liệu bên ngoài, chọn cách làm yếu tường thành, hạ gục Bastion và san phẳng sở chỉ huy."),
            ["mission.c1m10.fragment"] = ("Taken from the Bastion's crew after the fall: all eleven were contract engineers, not soldiers. The oldest had helped Mai weld her first Behemoth hull.", "Khai thác từ kíp lái Bastion sau khi pháo đài thất thủ: cả mười một người đều là kỹ sư hợp đồng, không phải lính. Người lớn tuổi nhất từng giúp Mai hàn vỏ chiếc Behemoth đầu tiên của cô."),
            ["mission.c1m10.fragment.title"] = ("The Bastion's crew", "Kíp lái Bastion"),
            ["mission.c1m10.name"] = ("The Ashfield Fortress", "Pháo đài Đồng Tro"),
            ["mission.c1s1.brief"] = ("Linh has heard engines in the fog round Greenvale's farms. Get a vehicle onto each of the three objectives and look before whatever is out there digs in.", "Linh nghe thấy tiếng động cơ trong sương quanh các trang trại Lũng Xanh. Đưa một xe tới từng cứ điểm trong ba cứ điểm để xem trước khi thứ gì ngoài đó kịp cố thủ."),
            ["mission.c1s1.fragment"] = ("\"Engines: three types. Diesel, heavy. Not Hegemon standard. Suggest someone else is selling them tanks.\" The note was filed, and forgotten, until chapter eight.", "\"Tiếng động cơ: ba loại. Máy dầu, hạng nặng. Không phải loại tiêu chuẩn của Hegemon. Đề nghị điều tra ai đang bán xe tăng cho chúng.\" Báo cáo được lưu lại, rồi bị quên, cho tới chương tám."),
            ["mission.c1s1.fragment.title"] = ("Linh's first report", "Báo cáo đầu tiên của Linh"),
            ["mission.c1s1.name"] = ("Tracks in the Fog", "Dấu xích trong sương"),
            ["mission.c1s2.brief"] = ("Mortar teams on the bluffs are shelling the beach every night. Linh has marked three of them. Hunt them down in the rain.", "Các khẩu đội cối trên vách đá đêm nào cũng nã vào bãi biển. Linh đã đánh dấu ba khẩu. Săn lùng chúng dưới mưa."),
            ["mission.c1s2.fragment"] = ("The mortar crews kept a tally on a door: 41 shells on the first night, 12 on the fifth. They were running out, and so was their nerve.", "Kíp cối ghi số đạn lên một cánh cửa: 41 quả đêm đầu, 12 quả đêm thứ năm. Chúng đang cạn đạn, và cạn cả gan."),
            ["mission.c1s2.fragment.title"] = ("The mortar crews", "Kíp cối"),
            ["mission.c1s2.name"] = ("Mortars on the Bluffs", "Cối trên vách đá"),
            ["mission.c2m01.brief"] = ("The brigade has reached Dunebreak's oil field. Hegemon wants it back before we can blow the wells. Hold out at the field for five minutes.", "Lữ đoàn đã tới mỏ dầu Đồi Cát. Hegemon muốn giành lại trước khi ta kịp phá giếng. Trụ vững ở mỏ dầu trong năm phút."),
            ["mission.c2m01.fragment"] = ("Hegemon's machines burn 40,000 barrels a day. Dunebreak and Red Rock pump 38,000. Varga has been complaining about the other two thousand for a year.", "Máy móc của Hegemon đốt 40.000 thùng dầu mỗi ngày. Đồi Cát và Hẻm Đá Đỏ bơm được 38.000. Varga đã cằn nhằn về hai nghìn thùng còn thiếu suốt một năm nay."),
            ["mission.c2m01.fragment.title"] = ("Black gold", "Vàng đen"),
            ["mission.c2m01.name"] = ("Oil and Sand", "Dầu và cát"),
            ["mission.c2m02.brief"] = ("Red Rock's wellhead, oasis and caravan stop feed the pipeline to Dunebreak. Varga's tanks hold the oasis. Take all three.", "Đầu giếng, ốc đảo và trạm dừng đoàn lạc đà ở Hẻm Đá Đỏ cấp dầu cho đường ống tới Đồi Cát. Xe tăng của Varga giữ ốc đảo. Chiếm cả ba."),
            ["mission.c2m02.fragment"] = ("Memo from General Varga to Director Aurel: \"I need the Red Rock wells, two more Behemoths and nobody from accounting in my headquarters.\" Aurel approved one of the three.", "Ghi nhớ của tướng Varga gửi giám đốc Aurel: \"Tôi cần giếng dầu Hẻm Đá Đỏ, thêm hai chiếc Behemoth và không có ai của phòng kế toán trong sở chỉ huy của tôi.\" Aurel duyệt một trong ba đề nghị."),
            ["mission.c2m02.fragment.title"] = ("Varga's memo", "Bản ghi nhớ của Varga"),
            ["mission.c2m02.name"] = ("The Wells of Red Rock", "Giếng dầu Hẻm Đá Đỏ"),
            ["mission.c2m03.brief"] = ("Fuel trucks for the brigade, through the canyon at night, past the oasis to the wellhead. Three of five must get through.", "Xe bồn nhiên liệu cho lữ đoàn, băng qua hẻm núi trong đêm, qua ốc đảo tới đầu giếng. Năm xe phải qua được ba."),
            ["mission.c2m03.fragment"] = ("The canyon road was a caravan route for five hundred years. The drivers still leave a stone at the oasis for luck. Ours did too.", "Con đường qua hẻm núi là tuyến đoàn lạc đà suốt năm trăm năm. Cánh tài xế vẫn đặt một hòn đá ở ốc đảo để cầu may. Tài xế của ta cũng thế."),
            ["mission.c2m03.fragment.title"] = ("The caravan road", "Đường đoàn lạc đà"),
            ["mission.c2m03.name"] = ("Night Caravan", "Đoàn xe đêm"),
            ["mission.c2m04.brief"] = ("Five pipeline stations carry Red Rock's oil into the refinery. Blow every one of them. A raid, no base: in fast, out faster.", "Năm trạm đường ống dẫn dầu từ Hẻm Đá Đỏ vào nhà máy lọc dầu. Cho nổ tung tất cả. Một trận đột kích, không căn cứ: vào nhanh, ra nhanh hơn."),
            ["mission.c2m04.fragment"] = ("Refinery log after the raid: \"Pressure zero on all lines. General Varga informed. General Varga has broken the telephone.\"", "Sổ nhật ký nhà máy sau trận đột kích: \"Áp suất bằng không trên mọi tuyến. Đã báo tướng Varga. Tướng Varga đã đập vỡ điện thoại.\""),
            ["mission.c2m04.fragment.title"] = ("Pressure", "Áp suất"),
            ["mission.c2m04.name"] = ("Cut the Pipeline", "Cắt đường ống"),
            ["mission.c2m05.brief"] = ("A land battleship crawls out of the sandstorm: Varga's Behemoth, the machine Mai helped build. Its main gun kills a tank a shot. Mai says the rear plates are thin. Bring it down.", "Một chiến hạm mặt đất bò ra từ bão cát: Behemoth của Varga, cỗ máy chính Mai từng góp tay chế tạo. Pháo chính của nó mỗi phát hạ một xe tăng. Mai nói giáp sau mỏng. Hạ gục nó."),
            ["mission.c2m05.fragment"] = ("Mai, quietly, after the battle: \"I welded the rear plates on that one. I used the thin ones because the thick ones were late. I never told anyone.\"", "Mai, khẽ nói sau trận: \"Tôi đã hàn các tấm giáp sau của chiếc đó. Tôi dùng loại mỏng vì loại dày về trễ. Tôi chưa bao giờ nói với ai.\""),
            ["mission.c2m05.fragment.title"] = ("Hull number one", "Thân tàu số một"),
            ["mission.c2m05.name"] = ("Behemoth", "Behemoth"),
            ["mission.c2m06.brief"] = ("Three of Varga's rocket and missile batteries hide among the mesas, marked in red. Find them in the sandstorm and knock them out.", "Ba dàn pháo phản lực và tên lửa của Varga ẩn giữa các khối đá, đánh dấu màu đỏ. Tìm ra chúng trong bão cát và tiêu diệt."),
            ["mission.c2m06.fragment"] = ("Varga's batteries call themselves the Scorpions and paint a tail on every launcher. After this afternoon, there were no more tails to paint.", "Các khẩu đội của Varga tự gọi mình là Bọ Cạp và vẽ một cái đuôi lên mỗi bệ phóng. Sau buổi chiều hôm đó, chẳng còn cái đuôi nào để vẽ nữa."),
            ["mission.c2m06.fragment.title"] = ("Scorpions", "Bọ cạp"),
            ["mission.c2m06.name"] = ("Scorpion Hunt", "Săn bọ cạp"),
            ["mission.c2m07.brief"] = ("A company of Red Rock militia has declared for the Alliance and is holding the oasis. Varga's tanks have it ringed. Break the ring before their HQ falls. The ring vehicles are marked.", "Một đại đội dân quân Hẻm Đá Đỏ đã tuyên bố đứng về phía Liên minh và đang giữ ốc đảo. Xe tăng của Varga vây kín họ. Phá vòng vây trước khi sở chỉ huy của họ thất thủ. Các xe vây được đánh dấu."),
            ["mission.c2m07.fragment"] = ("The militia captain's first words to Khai: \"We have been waiting two years. You are late.\" His second: \"Thank you.\"", "Câu đầu tiên của đại đội trưởng dân quân với Khải: \"Chúng tôi chờ hai năm rồi. Các anh tới muộn.\" Câu thứ hai: \"Cảm ơn.\""),
            ["mission.c2m07.fragment.title"] = ("Militia", "Dân quân"),
            ["mission.c2m07.name"] = ("The Oasis Garrison", "Đồn ốc đảo"),
            ["mission.c2m08.brief"] = ("We have a foot inside the refinery. Varga is throwing his reserve at it. Hold the refinery yard for four minutes.", "Ta đã đặt được một chân vào nhà máy lọc dầu. Varga đang tung lực lượng dự bị vào đó. Giữ sân nhà máy trong bốn phút."),
            ["mission.c2m08.fragment"] = ("The refinery's night shift hid in the cooling towers through the whole battle. In the morning they asked who was paying their wages now.", "Ca đêm của nhà máy trốn trong tháp làm mát suốt trận đánh. Sáng ra họ hỏi giờ ai sẽ trả lương cho họ."),
            ["mission.c2m08.fragment.title"] = ("Night shift", "Ca đêm"),
            ["mission.c2m08.name"] = ("Hold the Refinery", "Giữ nhà máy lọc dầu"),
            ["mission.c2m09.brief"] = ("Varga has dug his headquarters into the far end of the canyon: anti-tank guns, his favourite tanks, and his temper. Level his HQ. He will run; let him know we are coming.", "Varga đã đào sở chỉ huy vào cuối hẻm núi: pháo chống tăng, những chiếc xe tăng hắn ưng ý nhất, và cái tính nóng của hắn. San phẳng sở chỉ huy. Hắn sẽ chạy; để hắn biết ta đang tới."),
            ["mission.c2m09.fragment"] = ("Found in Varga's abandoned tent: a napkin with the first sketch of the Behemoth, dated eleven years ago. On the back, a shopping list. Linh framed it.", "Tìm thấy trong lều bỏ lại của Varga: một tờ giấy ăn với bản phác thảo đầu tiên của Behemoth, đề ngày mười một năm trước. Mặt sau là danh sách đồ cần mua. Linh đóng khung nó lại."),
            ["mission.c2m09.fragment.title"] = ("The napkin", "Tờ giấy ăn"),
            ["mission.c2m09.name"] = ("Varga's Camp", "Trại của Varga"),
            ["mission.c2m10.brief"] = ("The operation Varga fears: take the oil field and the oasis, choose what to hit next, then blow the refinery's towers and tanks. Linh says something is parked inside the refinery, and it runs on fire.", "Chiến dịch mà Varga sợ nhất: chiếm mỏ dầu và ốc đảo, chọn mục tiêu kế tiếp, rồi cho nổ tháp và bồn chứa của nhà máy. Linh nói có thứ gì đó đang đỗ bên trong nhà máy, và nó chạy bằng lửa."),
            ["mission.c2m10.fragment"] = ("Workshop order for the Inferno: \"Two flame projectors, one thermobaric box, cooling for the crew (optional).\" The cooling was never fitted.", "Phiếu đặt hàng xưởng cho Inferno: \"Hai súng phun lửa lớn, một hộp rốc-két nhiệt áp, hệ làm mát cho kíp lái (tùy chọn).\" Hệ làm mát chưa bao giờ được lắp."),
            ["mission.c2m10.fragment.title"] = ("Inferno", "Inferno"),
            ["mission.c2m10.name"] = ("Refinery Raid", "Đột kích nhà máy lọc dầu"),
            ["mission.c2s1.brief"] = ("Linh needs eyes on the oasis, the refinery and the oil field at night: Varga has been laying mines, and she wants to know where. Look, do not linger.", "Linh cần người tới xem ốc đảo, nhà máy và mỏ dầu trong đêm: Varga đang cho rải mìn, và cô muốn biết ở đâu. Nhìn rồi đi, đừng nấn ná."),
            ["mission.c2s1.fragment"] = ("The map Linh drew that night had 340 marks on it. The engineers cleared 338. Nobody found the other two, and nobody drives that way.", "Tấm bản đồ Linh vẽ đêm đó có 340 dấu. Công binh gỡ được 338. Không ai tìm ra hai quả còn lại, và không ai lái xe đi đường đó."),
            ["mission.c2s1.fragment.title"] = ("The mine map", "Tấm bản đồ mìn"),
            ["mission.c2s1.name"] = ("Minefield Maps", "Bản đồ bãi mìn"),
            ["mission.c2s2.brief"] = ("Varga has called in helicopters to hunt our convoys over Red Rock. Diều Hâu wants ten of them down before sunset. Bring your anti-air.", "Varga gọi trực thăng tới săn đoàn xe của ta trên Hẻm Đá Đỏ. Diều Hâu muốn bắn rơi mười chiếc trước khi mặt trời lặn. Mang phòng không theo."),
            ["mission.c2s2.fragment"] = ("Chalked on the hangar wall: \"Diều Hâu 10, Varga 0.\" Underneath, in smaller letters: \"Anti-air crews 9 of those.\"", "Viết phấn trên tường nhà chứa máy bay: \"Diều Hâu 10, Varga 0.\" Bên dưới, chữ nhỏ hơn: \"Trong đó 9 chiếc là của pháo thủ phòng không.\""),
            ["mission.c2s2.fragment.title"] = ("Diều Hâu's score", "Bảng điểm của Diều Hâu"),
            ["mission.c2s2.name"] = ("Varga's Gunships", "Trực thăng của Varga"),
            ["mission.c3m01.brief"] = ("The Whiteout pass is the only road north. Orlov's outposts hold its signal post, the frozen lake and the sawmill. Take all three in the snow.", "Đèo Bão Tuyết là con đường duy nhất lên phía bắc. Tiền đồn của Orlov giữ trạm tín hiệu, hồ băng và xưởng cưa. Chiếm cả ba trong tuyết."),
            ["mission.c3m01.fragment"] = ("Orlov's personnel file: \"Excellent. Cold. Has requested that his batteries be positioned further from the front. Again.\"", "Hồ sơ nhân sự của Orlov: \"Xuất sắc. Lạnh lùng. Lại đề nghị bố trí các khẩu đội của mình xa tiền tuyến hơn nữa.\""),
            ["mission.c3m01.fragment.title"] = ("Orlov", "Orlov"),
            ["mission.c3m01.name"] = ("Into the Pass", "Vào đèo"),
            ["mission.c3m02.brief"] = ("The first station of Orlov's radar line stands on the western heights. While it sees, his guns hit anything we move. Destroy it.", "Trạm đầu tiên trên tuyến radar của Orlov đứng trên cao điểm phía tây. Chừng nào nó còn nhìn thấy, pháo của hắn còn bắn trúng mọi thứ ta di chuyển. Phá hủy nó."),
            ["mission.c3m02.fragment"] = ("Seven stations from the coast to the mountains, each seeing eighty kilometres. With one gone, Orlov's map has a hole the size of a brigade.", "Bảy trạm từ bờ biển tới núi, mỗi trạm nhìn xa tám mươi cây số. Mất một trạm, tấm bản đồ của Orlov thủng một lỗ to bằng cả lữ đoàn."),
            ["mission.c3m02.fragment.title"] = ("The radar line", "Tuyến radar"),
            ["mission.c3m02.name"] = ("Blind the Radar", "Làm mù radar"),
            ["mission.c3m03.brief"] = ("The village in the valley is the only shelter for kilometres. Orlov wants it back, and the fog hides his guns. Hold it for three and a half minutes.", "Ngôi làng dưới thung lũng là chỗ trú duy nhất trong vòng nhiều cây số. Orlov muốn lấy lại, và sương mù che pháo của hắn. Giữ làng trong ba phút rưỡi."),
            ["mission.c3m03.fragment"] = ("The village priest rang the church bell every time Orlov's guns fired, so the brigade knew when to duck. He rang it 212 times.", "Cha xứ trong làng kéo chuông nhà thờ mỗi lần pháo Orlov khai hỏa, để lữ đoàn biết mà nằm xuống. Ông kéo 212 lần."),
            ["mission.c3m03.fragment.title"] = ("The church bell", "Tiếng chuông nhà thờ"),
            ["mission.c3m03.name"] = ("Village in the Fog", "Ngôi làng trong sương"),
            ["mission.c3m04.brief"] = ("Mai wants a forward base on the frozen lake, in the middle of the pass. Take the lake, set up an outpost and keep it three minutes. At night. On ice.", "Mai muốn dựng căn cứ tiền phương trên hồ băng, giữa đèo. Chiếm hồ, lập tiền đồn và giữ nó ba phút. Ban đêm. Trên băng."),
            ["mission.c3m04.fragment"] = ("Mai measured the ice herself: ninety centimetres. \"Enough for a tower, not for a Behemoth,\" she wrote. \"Good. That is the point.\"", "Mai tự tay đo băng: chín mươi phân. \"Đủ cho một cái tháp, không đủ cho một chiếc Behemoth,\" cô ghi. \"Tốt. Chính là thế.\""),
            ["mission.c3m04.fragment.title"] = ("Ice thickness", "Độ dày của băng"),
            ["mission.c3m04.name"] = ("Base on the Ice", "Căn cứ trên băng"),
            ["mission.c3m05.brief"] = ("Orlov's Iron Bird has come down from the clouds over the pass: a gunship the size of a ship, with rockets, flares and an escort. This is what the anti-air was for. Bring it down.", "Chim Sắt của Orlov đã sà xuống khỏi mây trên đèo: một pháo hạm bay to như con tàu, có rốc-két, pháo sáng mồi bẫy và đội hộ tống. Phòng không là để dành cho lúc này. Bắn rơi nó."),
            ["mission.c3m05.fragment"] = ("Iron Bird's crew manual, page one: \"The aircraft cannot be shot down by ground fire.\" Page two was missing. So, now, is Iron Bird.", "Sổ tay kíp lái Chim Sắt, trang một: \"Máy bay không thể bị hỏa lực mặt đất bắn hạ.\" Trang hai bị mất. Giờ thì Chim Sắt cũng mất."),
            ["mission.c3m05.fragment.title"] = ("Iron Bird", "Chim Sắt"),
            ["mission.c3m05.name"] = ("Iron Bird", "Chim Sắt"),
            ["mission.c3m06.brief"] = ("Linh has fixed three of Orlov's batteries by their muzzle flashes, marked in red. They move after every salvo. Hunt them in the dark.", "Linh đã định vị được ba khẩu đội của Orlov qua ánh chớp đầu nòng, đánh dấu màu đỏ. Chúng di chuyển sau mỗi loạt bắn. Săn chúng trong bóng tối."),
            ["mission.c3m06.fragment"] = ("Linh's method, in her own words: \"Count the seconds from the flash to the bang. Multiply. Draw a circle. Send Diều Hâu into the circle.\"", "Phương pháp của Linh, theo lời cô: \"Đếm số giây từ lúc chớp sáng tới tiếng nổ. Nhân lên. Vẽ một vòng tròn. Cho Diều Hâu bay vào vòng tròn đó.\""),
            ["mission.c3m06.fragment.title"] = ("Muzzle flash", "Chớp đầu nòng"),
            ["mission.c3m06.name"] = ("Orlov's Guns", "Pháo của Orlov"),
            ["mission.c3m07.brief"] = ("The families of the pass have taken shelter in the cabins and the barn on the south side. Orlov is shelling everything that still has a roof. Keep at least one standing for seven minutes.", "Các gia đình trên đèo đã trú trong những căn nhà gỗ và nhà kho phía nam. Orlov đang nã pháo vào mọi thứ còn mái che. Giữ ít nhất một căn đứng vững trong bảy phút."),
            ["mission.c3m07.fragment"] = ("Fifty-one people spent the night in the barn. In the morning a girl asked Diều Hâu if the loud planes were his. He said yes, and that they were on her side.", "Năm mươi mốt người qua đêm trong nhà kho. Sáng ra, một cô bé hỏi Diều Hâu có phải mấy chiếc máy bay ầm ĩ kia là của chú không. Anh bảo phải, và chúng đứng về phía cháu."),
            ["mission.c3m07.fragment.title"] = ("Fifty-one", "Năm mươi mốt người"),
            ["mission.c3m07.name"] = ("Cabins in the Snow", "Những căn nhà gỗ trong tuyết"),
            ["mission.c3m08.brief"] = ("The Behemoth from Dunebreak is back: Varga had it dragged north, repaired and heated for the snow, and lent it to Orlov. Heavier than before. Stop it for good.", "Chiếc Behemoth ở Đồi Cát đã quay lại: Varga cho kéo nó lên phía bắc, sửa chữa, lắp hệ sưởi cho tuyết, rồi cho Orlov mượn. Nặng hơn trước. Chặn đứng nó vĩnh viễn."),
            ["mission.c3m08.fragment"] = ("Varga to Orlov: \"Return it with a full tank.\" Orlov to Varga, a week later: \"Returned in several pieces. Tank empty.\"", "Varga gửi Orlov: \"Trả lại nhớ đổ đầy bình.\" Orlov gửi Varga, một tuần sau: \"Đã trả, thành nhiều mảnh. Bình rỗng.\""),
            ["mission.c3m08.fragment.title"] = ("A loan", "Khoản cho mượn"),
            ["mission.c3m08.name"] = ("Frozen Behemoth", "Behemoth Băng Giá"),
            ["mission.c3m09.brief"] = ("Orlov's headquarters sits behind a wall of artillery emplacements, where he can see the whole valley. Break through and level it. He will not wait for you.", "Sở chỉ huy của Orlov nằm sau một bức tường ụ pháo, nơi hắn nhìn thấy cả thung lũng. Chọc thủng và san phẳng nó. Hắn sẽ không chờ ta đâu."),
            ["mission.c3m09.fragment"] = ("Every page of Orlov's notebook is numbers: ranges, times, weights of shell. On the last page, one word, underlined: \"Why?\" Nobody knows what he was asking.", "Trang nào trong sổ tay của Orlov cũng toàn con số: tầm bắn, thời gian, trọng lượng đạn. Ở trang cuối có một chữ, gạch chân: \"Tại sao?\" Không ai biết hắn đã tự hỏi điều gì."),
            ["mission.c3m09.fragment.title"] = ("Orlov's notebook", "Sổ tay của Orlov"),
            ["mission.c3m09.name"] = ("Orlov's Gun Line", "Trận địa pháo của Orlov"),
            ["mission.c3m10.brief"] = ("The last station of the radar line, the fortress behind it, and the Ice Fortress guarding its gate. Blind the hill radar, choose your second blow, destroy the Ice Fortress, and hold its gate against Orlov's counterattack.", "Trạm cuối của tuyến radar, pháo đài phía sau nó, và Pháo Đài Băng canh cổng. Làm mù radar trên đồi, chọn đòn thứ hai, tiêu diệt Pháo Đài Băng, rồi giữ cổng trước đợt phản kích của Orlov."),
            ["mission.c3m10.fragment"] = ("The day the Frostpeak line fell, the thaw began. The engineers swear the two are not connected. The villagers do not believe the engineers.", "Ngày tuyến Đỉnh Sương Giá sụp đổ, băng bắt đầu tan. Công binh thề rằng hai chuyện chẳng liên quan gì nhau. Dân làng không tin công binh."),
            ["mission.c3m10.fragment.title"] = ("Spring", "Mùa xuân"),
            ["mission.c3m10.name"] = ("The Frostpeak Line", "Tuyến Đỉnh Sương Giá"),
            ["mission.c3s1.brief"] = ("Before the big push, Linh wants every gun position round Frostpeak on her map. Put a vehicle on the radar hill, the village and the lumber camp, in the fog.", "Trước trận đánh lớn, Linh muốn mọi trận địa pháo quanh Đỉnh Sương Giá có mặt trên bản đồ của cô. Đưa xe tới đồi radar, ngôi làng và trại gỗ, trong sương mù."),
            ["mission.c3s1.fragment"] = ("Linh keeps her maps on paper. \"Hegemon reads our radio,\" she says. \"Hegemon does not read my handwriting. Nobody does.\"", "Linh giữ bản đồ trên giấy. \"Hegemon đọc được sóng vô tuyến của ta,\" cô nói. \"Hegemon không đọc được chữ tôi. Chẳng ai đọc được.\""),
            ["mission.c3s1.fragment.title"] = ("Paper map", "Bản đồ giấy"),
            ["mission.c3s1.name"] = ("Where the Guns Are", "Pháo nằm ở đâu"),
            ["mission.c3s2.brief"] = ("Medicine and doctors for the signal post, where the wounded from the pass are waiting. Five trucks at night; three must get there.", "Thuốc men và bác sĩ cho trạm tín hiệu, nơi thương binh trên đèo đang chờ. Năm xe trong đêm; phải tới được ba xe."),
            ["mission.c3s2.fragment"] = ("The convoy's doctor had worked for Hegemon's medical corps until the Night of Steel. Nobody asked her why she changed sides. She did not wait to be asked.", "Bác sĩ trong đoàn xe từng làm cho quân y Hegemon cho tới Đêm Thép. Không ai hỏi vì sao cô đổi phe. Cô cũng chẳng đợi ai hỏi."),
            ["mission.c3s2.fragment.title"] = ("The doctor", "Bác sĩ"),
            ["mission.c3s2.name"] = ("Medical Convoy", "Đoàn xe cứu thương"),
            ["mission.c4m01.brief"] = ("Kessler's marshalling yard feeds the port. Take the foundry, the yard and the scrapyard, and his trains have nowhere to be put together.", "Bãi dồn toa của Kessler nuôi cả bến cảng. Chiếm xưởng đúc, bãi dồn toa và bãi phế liệu, các đoàn tàu của hắn sẽ không còn chỗ lắp ráp."),
            ["mission.c4m01.fragment"] = ("A Rust Yard timetable, pinned in the signal box: 212 trains a week, each to the minute. Handwritten at the bottom: \"Delays will be explained to the Admiral in person.\"", "Một bảng giờ tàu ở Bãi Sắt Gỉ, ghim trong trạm tín hiệu: 212 chuyến mỗi tuần, chính xác tới từng phút. Viết tay ở dưới: \"Chuyến nào trễ sẽ phải giải trình trực tiếp với Đô đốc.\""),
            ["mission.c4m01.fragment.title"] = ("The timetable", "Thời gian biểu"),
            ["mission.c4m01.name"] = ("The Rust Yard", "Bãi Sắt Gỉ"),
            ["mission.c4m02.brief"] = ("Kessler holds the docks, the factories and the rail yard of Ironport. Take all three in the rain, and set up an outpost in the factories.", "Kessler giữ bến tàu, khu nhà máy và bãi đường sắt của Cảng Thép. Chiếm cả ba dưới mưa, và lập tiền đồn trong khu nhà máy."),
            ["mission.c4m02.fragment"] = ("Every Behemoth hull left Ironport by sea. Mai recognised the factory's crane from the other side: she used to sign for the plates it lifted.", "Mọi thân tàu Behemoth đều rời Cảng Thép bằng đường biển. Mai nhận ra cây cần cẩu của nhà máy, từ phía bên kia: cô từng ký nhận những tấm thép nó nâng."),
            ["mission.c4m02.fragment.title"] = ("Made in Ironport", "Sản xuất tại Cảng Thép"),
            ["mission.c4m02.name"] = ("Storm the Factories", "Đánh chiếm khu nhà máy"),
            ["mission.c4m03.brief"] = ("Engineers and explosives for the docks, five trucks through the fogbound port. Three must reach the quay.", "Công binh và thuốc nổ cho bến tàu, năm xe tải xuyên qua bến cảng chìm trong sương. Phải tới được cầu tàu ba xe."),
            ["mission.c4m03.fragment"] = ("The port's fog horn sounds every ninety seconds. The drivers timed their dashes between the blasts, so the enemy could not hear the engines.", "Còi sương của bến cảng rú lên mỗi chín mươi giây. Cánh tài xế canh giờ lao xe vào giữa hai tiếng còi để địch không nghe thấy tiếng máy."),
            ["mission.c4m03.fragment.title"] = ("Fog horn", "Còi sương"),
            ["mission.c4m03.name"] = ("Dockside Convoy", "Đoàn xe bến cảng"),
            ["mission.c4m04.brief"] = ("Linh needs to know where the steel train is being put together. Get a vehicle onto each of the three objectives and look, before Kessler digs in.", "Linh cần biết đoàn tàu thép đang được lắp ráp ở đâu. Đưa xe tới từng cứ điểm trong ba cứ điểm để quan sát, trước khi Kessler kịp cố thủ."),
            ["mission.c4m04.fragment"] = ("Linh copied the numbers off every wagon in the yard. Eleven of them came up twice in Kessler's own lists: the steel train, hiding in plain sight.", "Linh chép lại số hiệu của mọi toa tàu trong bãi. Mười một số xuất hiện hai lần trong chính danh sách của Kessler: đoàn tàu thép, trốn ngay trước mắt."),
            ["mission.c4m04.fragment.title"] = ("Wagon numbers", "Số hiệu toa"),
            ["mission.c4m04.name"] = ("Eyes on the Yard", "Mắt nhìn Bãi Sắt"),
            ["mission.c4m05.brief"] = ("Kessler's armoured train is running for the docks with a cargo Linh does not like the sound of. Destroy it before it arrives.", "Đoàn tàu bọc thép của Kessler đang lao về bến tàu với một chuyến hàng mà Linh nghe tên đã thấy không ổn. Phá hủy nó trước khi nó tới nơi."),
            ["mission.c4m05.fragment"] = ("The train's manifest, recovered from the wreck: forty tons of \"laboratory equipment\" addressed to \"Project S.B., Skyhold\". The first time anyone read those two letters.", "Bản kê hàng của đoàn tàu, tìm thấy trong xác tàu: bốn mươi tấn \"thiết bị phòng thí nghiệm\" gửi tới \"Dự án S.B., Tầng Mây\". Lần đầu tiên có người đọc thấy hai chữ cái đó."),
            ["mission.c4m05.fragment.title"] = ("The cargo", "Chuyến hàng"),
            ["mission.c4m05.name"] = ("The Steel Train", "Đoàn tàu thép"),
            ["mission.c4m06.brief"] = ("Kessler has a gun too big for any road, parked on the rails at the edge of the Rust Yard. Every twenty seconds it drops a shell on us, and the ground warns us three seconds before. Fight through its guard and destroy it.", "Kessler có một khẩu pháo quá to cho mọi con đường, đậu trên đường ray ở rìa Bãi Sắt Gỉ. Cứ hai mươi giây nó lại nã một phát vào ta, và mặt đất báo trước ba giây. Đánh xuyên qua đội canh gác và phá hủy nó."),
            ["mission.c4m06.fragment"] = ("The supergun's range card says forty kilometres. Its crew manual says: \"Do not fire within forty kilometres of the Admiral.\" He was never that far from it.", "Bảng tầm bắn của siêu pháo ghi bốn mươi cây số. Sổ tay kíp pháo ghi: \"Không được bắn khi Đô đốc ở trong vòng bốn mươi cây số.\" Ông ta chưa từng rời xa nó tới thế."),
            ["mission.c4m06.fragment.title"] = ("Forty kilometres", "Bốn mươi cây số"),
            ["mission.c4m06.name"] = ("The Rail Supergun", "Siêu pháo đường ray"),
            ["mission.c4m07.brief"] = ("We hold the factory district now, and the workers are back at their benches. Kessler is coming from the south to burn it rather than lose it. Keep at least one building standing for seven minutes.", "Giờ ta giữ khu nhà máy, và công nhân đã quay lại bàn máy. Kessler đang kéo tới từ phía nam để đốt trụi nó chứ không chịu mất. Giữ ít nhất một tòa nhà đứng vững trong bảy phút."),
            ["mission.c4m07.fragment"] = ("The factory's foreman stayed at his post through the whole attack. Asked why, he said: \"Somebody has to switch the furnaces off properly. Hegemon never did.\"", "Ông đốc công bám trụ ở vị trí suốt trận tấn công. Hỏi vì sao, ông bảo: \"Phải có người tắt lò cho đúng cách. Bọn Hegemon chẳng bao giờ làm.\""),
            ["mission.c4m07.fragment.title"] = ("The foreman", "Ông đốc công"),
            ["mission.c4m07.name"] = ("Kessler Strikes Back", "Kessler phản đòn"),
            ["mission.c4m08.brief"] = ("Every night Kessler's minelayers seed the roads to the port. Linh has marked three of them. Hunt them before they finish their round.", "Đêm nào các xe rải mìn của Kessler cũng gieo mìn khắp những con đường vào cảng. Linh đã đánh dấu ba chiếc. Săn chúng trước khi chúng xong một vòng."),
            ["mission.c4m08.fragment"] = ("Kessler's mines are numbered, dated and logged. His engineers could tell us the exact place of every one. They did, for a hot meal each.", "Mìn của Kessler được đánh số, ghi ngày và vào sổ. Công binh của hắn có thể chỉ cho ta chính xác vị trí từng quả. Và họ đã chỉ, đổi lấy mỗi người một bữa ăn nóng."),
            ["mission.c4m08.fragment.title"] = ("Kessler's mines", "Mìn của Kessler"),
            ["mission.c4m08.name"] = ("Minelayers", "Tàu rải mìn trên cạn"),
            ["mission.c4m09.brief"] = ("Kessler's headquarters stands behind the container stacks at the north end of the port, a little of every defence and mines everywhere. Break it in the storm and level his HQ.", "Sở chỉ huy của Kessler nằm sau những dãy công-te-nơ ở đầu bắc bến cảng, phòng thủ thứ gì cũng có một ít và mìn ở khắp nơi. Phá nó giữa cơn bão và san phẳng sở chỉ huy."),
            ["mission.c4m09.fragment"] = ("Kessler's logbook, last entry before the storm: \"Weather: unacceptable. Enemy: unacceptable. Morale: acceptable.\" He took the logbook with him when he ran.", "Sổ nhật ký của Kessler, dòng cuối trước cơn bão: \"Thời tiết: không chấp nhận được. Quân địch: không chấp nhận được. Tinh thần: chấp nhận được.\" Hắn mang theo cuốn sổ khi tháo chạy."),
            ["mission.c4m09.fragment.title"] = ("The logbook", "Cuốn sổ nhật ký"),
            ["mission.c4m09.name"] = ("The Admiral's Quarters", "Tổng hành dinh của Đô đốc"),
            ["mission.c4m10.brief"] = ("The whole port, in one day: the rail yard, then the factories and the docks. On the quay, Linh's intercepts say, Tempest is waiting with its railgun. Take everything, destroy Tempest, and hold the quay against Kessler's last counterattack.", "Cả bến cảng, trong một ngày: bãi đường sắt, rồi khu nhà máy và bến tàu. Trên cầu tàu, theo các bản chặn thu của Linh, Tempest đang chờ với khẩu súng điện từ. Chiếm tất cả, tiêu diệt Tempest, rồi giữ cầu tàu trước đợt phản công cuối cùng của Kessler."),
            ["mission.c4m10.fragment"] = ("Kessler shipped Tempest to the docks so it could sail if the port fell. It never sailed. Its railgun now points at the sea, in the brigade's museum yard.", "Kessler đưa Tempest ra bến để nó kịp xuống tàu nếu cảng thất thủ. Nó chưa bao giờ xuống tàu. Giờ khẩu súng điện từ của nó chĩa ra biển, trong sân bảo tàng của lữ đoàn."),
            ["mission.c4m10.fragment.title"] = ("Tempest", "Tempest"),
            ["mission.c4m10.name"] = ("Take the Port", "Chiếm bến cảng"),
            ["mission.c4s1.brief"] = ("Linh has found where Kessler keeps the Alliance prisoners: a siding at the scrapyard. Four trucks to bring them out; three must make it.", "Linh đã tìm ra nơi Kessler giam giữ tù binh Liên minh: một đường tránh ở bãi phế liệu. Bốn xe tải để đưa họ ra; phải thoát được ba xe."),
            ["mission.c4s1.fragment"] = ("Eighty-four prisoners came out of the siding. Linh read every name over the radio that night, so their families would hear.", "Tám mươi tư tù binh được đưa ra khỏi đường tránh. Đêm đó Linh đọc từng cái tên trên sóng phát thanh, để gia đình họ được nghe."),
            ["mission.c4s1.fragment.title"] = ("Names", "Những cái tên"),
            ["mission.c4s1.name"] = ("The Prisoners' Train", "Chuyến tàu tù binh"),
            ["mission.c4s2.brief"] = ("Two of Kessler's harbour masters are still running the smuggling routes from command cars. Linh has marked them. Bring them in, the hard way.", "Hai viên cảng vụ của Kessler vẫn đang điều hành các tuyến buôn lậu từ xe chỉ huy. Linh đã đánh dấu họ. Bắt họ về, bằng cách khó."),
            ["mission.c4s2.fragment"] = ("The harbour masters' ledger listed every buyer of Hegemon weapons on the coast. One name had been crossed out and written again in ink: Hùng.", "Sổ sách của các viên cảng vụ ghi tên mọi kẻ mua vũ khí Hegemon trên dải duyên hải. Một cái tên bị gạch đi rồi viết lại bằng mực: Hùng."),
            ["mission.c4s2.fragment.title"] = ("The smugglers' ledger", "Sổ sách buôn lậu"),
            ["mission.c4s2.name"] = ("Harbour Masters", "Những viên cảng vụ"),
            ["mission.c5m01.brief"] = ("Sen's outer guard holds the temple ford and the east village of the Jungle Pass. Take the whole pass in the rain.", "Lực lượng canh gác vòng ngoài của Sen giữ bến đền cổ và làng phía đông Đèo Rừng Rậm. Chiếm trọn con đèo dưới mưa."),
            ["mission.c5m01.fragment"] = ("The temple in the pass is eight hundred years old. Sen's engineers used its courtyard to test drones, and left the carvings alone. Linh noticed that.", "Ngôi đền trên đèo đã tám trăm năm tuổi. Kỹ sư của Sen dùng sân đền để thử drone, nhưng không đụng tới những bức chạm khắc. Linh để ý điều đó."),
            ["mission.c5m01.fragment.title"] = ("The temple", "Ngôi đền"),
            ["mission.c5m01.name"] = ("Temple of Ash", "Đền Tro"),
            ["mission.c5m02.brief"] = ("Three of Sen's launch trucks send drone swarms over the lava fields every night. Linh has marked them. Hunt them in the glow of the lava.", "Ba xe phóng của Sen đêm nào cũng tung bầy drone qua đồng dung nham. Linh đã đánh dấu chúng. Săn chúng dưới ánh sáng của dung nham."),
            ["mission.c5m02.fragment"] = ("Every one of Sen's drones carries a serial number and a single word stamped under the wing: \"Sorry.\" Nobody in Hegemon ever turned one over.", "Mỗi chiếc drone của Sen đều mang một số hiệu và một chữ duy nhất đóng dưới cánh: \"Xin lỗi.\" Chưa ai bên Hegemon từng lật một chiếc lên mà xem."),
            ["mission.c5m02.fragment.title"] = ("Drone serials", "Số hiệu drone"),
            ["mission.c5m02.name"] = ("Swarm Trucks", "Xe bầy đàn"),
            ["mission.c5m03.brief"] = ("Bridging gear for the engineers, up the river road through the jungle fog to the west village. Three of five trucks must arrive; Sen's drones will be looking for them.", "Thiết bị bắc cầu cho công binh, ngược đường ven sông qua sương rừng tới làng phía tây. Năm xe phải tới được ba; drone của Sen sẽ săn lùng chúng."),
            ["mission.c5m03.fragment"] = ("The engineers built four bridges over the river in two days. The villagers named the last one after the brigade. The brigade named it after the villagers.", "Công binh bắc bốn cây cầu qua sông trong hai ngày. Dân làng đặt tên cây cầu cuối theo tên lữ đoàn. Lữ đoàn lại đặt tên nó theo tên dân làng."),
            ["mission.c5m03.fragment.title"] = ("The bridges", "Những cây cầu"),
            ["mission.c5m03.name"] = ("River Road", "Đường ven sông"),
            ["mission.c5m04.brief"] = ("Mai wants the geothermal plant in the middle of Ember Ridge: free power for a forward base. Take it, set up an outpost, keep it three minutes.", "Mai muốn lấy nhà máy địa nhiệt giữa Sườn Dung Nham: điện miễn phí cho một căn cứ tiền phương. Chiếm nó, lập tiền đồn, giữ ba phút."),
            ["mission.c5m04.fragment"] = ("Mai's note on the plant: \"Output 40 MW. Enough for the base, the airfield and the coffee machine. In that order. No, reverse that order.\"", "Ghi chú của Mai về nhà máy: \"Công suất 40 MW. Đủ cho căn cứ, sân bay và máy pha cà phê. Theo thứ tự đó. À không, đảo ngược thứ tự đó.\""),
            ["mission.c5m04.fragment.title"] = ("Free power", "Điện miễn phí"),
            ["mission.c5m04.name"] = ("The Geothermal Plant", "Nhà máy địa nhiệt"),
            ["mission.c5m05.brief"] = ("Sen's drone fortress is crawling down the pass in the storm, swarms rising from its racks. It has no main gun and fears no aircraft. Break it with tanks and artillery.", "Pháo đài drone của Sen đang bò xuống con đèo trong cơn bão, bầy drone bốc lên từ các giàn phóng. Nó không có pháo chính và chẳng sợ máy bay nào. Đập vỡ nó bằng xe tăng và pháo binh."),
            ["mission.c5m05.fragment"] = ("The Hive's original design document, found in its wreck: \"Autonomous swarm for search and rescue in disaster zones.\" The word \"rescue\" had been crossed out, by someone else.", "Tài liệu thiết kế gốc của Tổ Ong, tìm thấy trong xác nó: \"Bầy drone tự hành phục vụ tìm kiếm cứu nạn ở vùng thảm họa.\" Chữ \"cứu nạn\" đã bị gạch đi, bởi một người khác."),
            ["mission.c5m05.fragment.title"] = ("Rescue system", "Hệ thống cứu hộ"),
            ["mission.c5m05.name"] = ("The Hive", "Tổ Ong"),
            ["mission.c5m06.brief"] = ("The drone works are inside a fortress at the north end of the ridge. Break through the walls at night and level the command HQ.", "Xưởng drone nằm trong một pháo đài ở đầu bắc sườn núi. Phá tường trong đêm và san phẳng sở chỉ huy."),
            ["mission.c5m06.fragment"] = ("Inside the drone works: 4,000 drones in crates, and one office with a camp bed. Sen had not been home in eight months.", "Bên trong xưởng drone: 4.000 chiếc drone còn trong thùng, và một văn phòng kê một chiếc giường gấp. Sen đã tám tháng không về nhà."),
            ["mission.c5m06.fragment.title"] = ("The works", "Xưởng máy"),
            ["mission.c5m06.name"] = ("Molten Gate", "Cổng Dung Nham"),
            ["mission.c5m07.brief"] = ("Sen's strike drones own the sky over the pass. Bring fourteen of them down, and the jungle belongs to the brigade again.", "Drone tấn công của Sen làm chủ bầu trời trên đèo. Bắn rơi mười bốn chiếc, và rừng lại thuộc về lữ đoàn."),
            ["mission.c5m07.fragment"] = ("After the drones were gone, the birds came back to the pass within a week. Diều Hâu claims they were waiting for him.", "Lũ drone biến mất được một tuần thì chim chóc quay về đèo. Diều Hâu khẳng định chúng đợi anh."),
            ["mission.c5m07.fragment.title"] = ("Birds", "Chim chóc"),
            ["mission.c5m07.name"] = ("Clear the Canopy", "Quét sạch tán rừng"),
            ["mission.c5m08.brief"] = ("The geothermal plant's steam tanks power the whole brigade now. Sen's drones are coming for them from the south. Keep at least one standing for seven minutes.", "Các bồn hơi của nhà máy địa nhiệt giờ cấp điện cho cả lữ đoàn. Drone của Sen đang lao tới từ phía nam. Giữ ít nhất một bồn đứng vững trong bảy phút."),
            ["mission.c5m08.fragment"] = ("Intercepted, from Sen to Aurel: \"The plant is a civilian power source. I will not strike it.\" Aurel's reply: \"Then someone else will.\" Someone else did.", "Chặn thu được, Sen gửi Aurel: \"Nhà máy là nguồn điện dân sự. Tôi sẽ không đánh nó.\" Aurel trả lời: \"Vậy sẽ có người khác đánh.\" Và đã có người khác đánh."),
            ["mission.c5m08.fragment.title"] = ("A message", "Một bức điện"),
            ["mission.c5m08.name"] = ("Keep the Lights On", "Giữ đèn sáng"),
            ["mission.c5m09.brief"] = ("Sen's field headquarters is ringed with drone hangars and jammers. Break it at night and level her HQ. Linh thinks she may not fight to the end.", "Sở chỉ huy dã chiến của Sen được bao quanh bởi những nhà chứa drone và xe gây nhiễu. Phá nó trong đêm và san phẳng sở chỉ huy. Linh nghĩ bà ấy có thể sẽ không đánh tới cùng."),
            ["mission.c5m09.fragment"] = ("Sen's last message before her HQ fell, on an open channel: \"Colonel, if we meet, I would like to talk. Not about drones.\" Khai did not answer. He kept the recording.", "Bức điện cuối của Sen trước khi sở chỉ huy thất thủ, trên kênh mở: \"Đại tá, nếu ta gặp nhau, tôi muốn nói chuyện. Không phải về drone.\" Khải không trả lời. Ông giữ lại bản ghi âm."),
            ["mission.c5m09.fragment.title"] = ("An open channel", "Một kênh mở"),
            ["mission.c5m09.name"] = ("The Hangars of the Pass", "Những nhà chứa trên đèo"),
            ["mission.c5m10.brief"] = ("The Hive's mothership is over Ember Ridge, feeding swarms to every Hegemon unit in the jungle. Take the causeways, choose your next blow, survive the swarm it throws at you, then bring the mothership down.", "Tàu mẹ của Tổ Ong đang lơ lửng trên Sườn Dung Nham, tiếp bầy drone cho mọi đơn vị Hegemon trong rừng. Chiếm các đường đắp, chọn đòn kế tiếp, trụ vững trước bầy drone nó tung ra, rồi bắn rơi tàu mẹ."),
            ["mission.c5m10.fragment"] = ("Dr Sen walked out of the burning works with her hands up and a hard drive in each. \"Silver Bug,\" she said. \"You need to see this. Now.\"", "Tiến sĩ Sen bước ra khỏi xưởng đang cháy, hai tay giơ cao, mỗi tay cầm một ổ cứng. \"Bọ Bạc,\" bà nói. \"Các anh cần xem cái này. Ngay bây giờ.\""),
            ["mission.c5m10.fragment.title"] = ("Sen", "Sen"),
            ["mission.c5m10.name"] = ("The Mothership", "Tàu mẹ"),
            ["mission.c5s1.brief"] = ("Somewhere in the pass Sen keeps a laboratory off Hegemon's books. Linh wants to find it first. Look at all three objectives.", "Đâu đó trên đèo, Sen có một phòng thí nghiệm không có trong sổ sách của Hegemon. Linh muốn tìm ra nó trước. Quan sát cả ba cứ điểm."),
            ["mission.c5s1.fragment"] = ("In Sen's hidden lab: rescue drones, painted orange, with medical kits in their bays. Hundreds of them, never armed. She had been building the Hive she wanted.", "Trong phòng thí nghiệm bí mật của Sen: drone cứu hộ, sơn màu cam, trong khoang chứa túi cứu thương. Hàng trăm chiếc, chưa bao giờ gắn vũ khí. Bà vẫn đang chế tạo Tổ Ong mà bà mong muốn."),
            ["mission.c5s1.fragment.title"] = ("The second lab", "Phòng thí nghiệm thứ hai"),
            ["mission.c5s1.name"] = ("Sen's Laboratory", "Phòng thí nghiệm của Sen"),
            ["mission.c5s2.brief"] = ("The charcoal burners of the ridge have held out against Hegemon for two years in a fortified camp. Now they are ringed. Break the ring; the besiegers are marked.", "Dân đốt than trên sườn núi đã cầm cự với Hegemon suốt hai năm trong một trại có rào lũy. Giờ họ bị vây kín. Phá vòng vây; quân vây được đánh dấu."),
            ["mission.c5s2.fragment"] = ("The burners paid the brigade in charcoal. Mai used it in the base forge for a month and said it was the best she had ever worked with.", "Dân đốt than trả công lữ đoàn bằng than củi. Mai dùng nó trong lò rèn của căn cứ suốt một tháng và bảo đó là loại than tốt nhất cô từng dùng."),
            ["mission.c5s2.fragment.title"] = ("Charcoal", "Than củi"),
            ["mission.c5s2.name"] = ("The Charcoal Burners", "Làng đốt than"),
            ["mission.c6m01.brief"] = ("Hegemon strikes back where we first won. Varga is throwing his armour at the Ashfield fortress, ours now, towers and all. Keep its command HQ standing for eight minutes.", "Hegemon phản đòn đúng nơi ta giành chiến thắng đầu tiên. Varga đang tung thiết giáp vào pháo đài Đồng Tro, giờ là của ta, cả tháp lẫn tường. Giữ sở chỉ huy của nó đứng vững trong tám phút."),
            ["mission.c6m01.fragment"] = ("The fortress's old kilns held again, this time for us. Mai had reinforced them with the Bastion's own plates. \"Recycling,\" she called it.", "Những lò nung cũ của pháo đài lại trụ vững, lần này là cho ta. Mai đã gia cố chúng bằng chính những tấm giáp của Bastion. Cô gọi đó là \"tái chế\"."),
            ["mission.c6m01.fragment.title"] = ("The kilns again", "Lại là lò nung"),
            ["mission.c6m01.name"] = ("Ashfield Under Fire", "Đồng Tro rực lửa"),
            ["mission.c6m02.brief"] = ("Varga's counterstrike is pouring over the pass. The villagers at the frozen lake have to get out: six trucks, one every few seconds, down the road to our camp. Hold the lake until the last one leaves, then cover the road. Four must get through.", "Đợt phản công của Varga đang tràn qua đèo. Dân làng ở hồ băng phải rời đi: sáu xe tải, cứ vài giây một chiếc, theo đường về trại của ta. Giữ hồ cho tới khi xe cuối cùng rời đi, rồi yểm trợ con đường. Phải thoát được bốn xe."),
            ["mission.c6m02.fragment"] = ("The last truck out of Whiteout carried the church bell of the village in the valley. The priest would not leave without it. Nobody argued.", "Chiếc xe cuối cùng rời Đèo Bão Tuyết chở theo quả chuông nhà thờ của ngôi làng dưới thung lũng. Cha xứ không chịu đi nếu không có nó. Chẳng ai cãi."),
            ["mission.c6m02.fragment.title"] = ("The last truck", "Chiếc xe cuối cùng"),
            ["mission.c6m02.name"] = ("Evacuate Whiteout", "Sơ tán Đèo Bão Tuyết"),
            ["mission.c6m03.brief"] = ("Mai has done it: the Behemoth from the Ashfield yard runs, and it is ours. Escort it from the fortress across Ashfield to the front. Varga will do anything to stop his own machine.", "Mai đã làm được: chiếc Behemoth trong sân pháo đài Đồng Tro đã chạy, và nó là của ta. Hộ tống nó từ pháo đài băng qua Đồng Tro ra tiền tuyến. Varga sẽ làm mọi cách để chặn chính cỗ máy của hắn."),
            ["mission.c6m03.fragment"] = ("Mai named the captured Behemoth \"Bà Già\" (the Old Lady). Its crew painted a flower on the rear plates, over the weld she had never told anyone about.", "Mai đặt tên chiếc Behemoth bắt được là \"Bà Già\". Kíp lái vẽ một bông hoa lên tấm giáp sau, đè lên đường hàn cô chưa từng kể với ai."),
            ["mission.c6m03.fragment.title"] = ("Mai's Behemoth", "Behemoth của Mai"),
            ["mission.c6m03.name"] = ("Our Behemoth", "Behemoth của ta"),
            ["mission.c6m04.brief"] = ("Varga is making for the Hydro Dam that lights half the coast. Get there first: the power station, the road bridge and the ford.", "Varga đang nhắm tới Đập Thủy Điện, nơi thắp sáng nửa dải duyên hải. Tới đó trước hắn: trạm phát điện, cầu đường bộ và bến lội."),
            ["mission.c6m04.fragment"] = ("The Hydro Dam's turbines light every town from Greenvale to Ironport. When Hegemon took the coast, the dam was the only thing its engineers asked to keep running.", "Tua-bin của Đập Thủy Điện thắp sáng mọi thị trấn từ Lũng Xanh tới Cảng Thép. Khi Hegemon chiếm dải duyên hải, con đập là thứ duy nhất các kỹ sư của chúng xin được giữ cho chạy."),
            ["mission.c6m04.fragment.title"] = ("Half the coast", "Nửa dải duyên hải"),
            ["mission.c6m04.name"] = ("The Dam Valley", "Thung lũng con đập"),
            ["mission.c6m05.brief"] = ("Something is circling high over the pass at night, and every time it passes, a tank burns. Spectre: a gunship that never comes low. Only anti-air and fighters can reach it. Bring it down.", "Có thứ gì đó bay vòng trên cao trên đèo trong đêm, và mỗi lần nó lướt qua là một chiếc xe tăng bốc cháy. Spectre: pháo hạm bay không bao giờ hạ thấp. Chỉ phòng không và tiêm kích với tới nó. Bắn rơi nó."),
            ["mission.c6m05.fragment"] = ("Spectre's crew called themselves \"the Ghosts\" and never landed at the same base twice. They landed once more, in pieces, on the frozen lake.", "Kíp lái Spectre tự gọi mình là \"những Bóng Ma\" và không bao giờ hạ cánh hai lần ở cùng một căn cứ. Chúng đã hạ cánh thêm một lần nữa, thành từng mảnh, trên hồ băng."),
            ["mission.c6m05.fragment.title"] = ("The ghost", "Bóng ma"),
            ["mission.c6m05.name"] = ("Spectre", "Bóng ma Spectre"),
            ["mission.c6m06.brief"] = ("The road bridge below the dam is the only way across for heavy armour. Hold it in the fog for four minutes. The bridge must not fall into Varga's hands.", "Cây cầu đường bộ dưới chân đập là lối duy nhất cho thiết giáp hạng nặng vượt sông. Giữ nó trong sương mù bốn phút. Không được để cây cầu rơi vào tay Varga."),
            ["mission.c6m06.fragment"] = ("The bridge was built in 1962 and rated for thirty tons. The brigade ran sixty-ton tanks across it all day. Mai does not want to talk about it.", "Cây cầu xây năm 1962, thiết kế chịu tải ba mươi tấn. Lữ đoàn cho xe tăng sáu mươi tấn chạy qua cả ngày. Mai không muốn nhắc tới chuyện đó."),
            ["mission.c6m06.fragment.title"] = ("The bridge", "Cây cầu"),
            ["mission.c6m06.name"] = ("Hold the Bridge", "Giữ cây cầu"),
            ["mission.c6m07.brief"] = ("Varga has ringed Ashfield town, where the Alliance militia keep their HQ. Break the ring before it falls; the besiegers are marked.", "Varga đã vây kín thị trấn Đồng Tro, nơi dân quân Liên minh đặt sở chỉ huy. Phá vòng vây trước khi nó thất thủ; quân vây được đánh dấu."),
            ["mission.c6m07.fragment"] = ("The militia had rebuilt the town square with bricks from the old kilns. Varga's guns knocked half of it down. They started rebuilding before the smoke cleared.", "Dân quân đã xây lại quảng trường bằng gạch từ những lò nung cũ. Pháo của Varga bắn sập một nửa. Khói chưa tan, họ đã bắt đầu xây lại."),
            ["mission.c6m07.fragment.title"] = ("Bricks", "Gạch"),
            ["mission.c6m07.name"] = ("The Town Garrison", "Đồn thị trấn"),
            ["mission.c6m08.brief"] = ("Varga's tunnelling machine is grinding under the valley towards the power station. If it gets there, the dam loses its heart. Stop it on the way.", "Cỗ máy khoan của Varga đang nghiến xuyên dưới thung lũng hướng về trạm phát điện. Nó mà tới nơi, con đập mất trái tim. Chặn nó giữa đường."),
            ["mission.c6m08.fragment"] = ("Sâu Đất was built to dig mines. Varga fitted it with guns and a battering head. Its original crew, miners from Red Rock, refused to drive it. He found another crew.", "Sâu Đất được chế tạo để đào mỏ. Varga gắn thêm pháo và một đầu húc. Kíp lái cũ, thợ mỏ ở Hẻm Đá Đỏ, từ chối lái nó. Hắn tìm kíp khác."),
            ["mission.c6m08.fragment.title"] = ("The earthworm", "Con giun đất"),
            ["mission.c6m08.name"] = ("Sâu Đất", "Sâu Đất"),
            ["mission.c6m09.brief"] = ("Varga has made his winter camp in the south of the pass, in our old positions, and dug in every anti-tank gun he has. Level his HQ, and his counterstrike has no head.", "Varga dựng trại mùa đông ở phía nam đèo, ngay trên các vị trí cũ của ta, và đào sẵn mọi khẩu pháo chống tăng hắn có. San phẳng sở chỉ huy, đợt phản công của hắn sẽ mất đầu."),
            ["mission.c6m09.fragment"] = ("Varga's supply officer, captured at the camp: \"He said he would build two tanks for every one you burned. He stopped saying it in November.\"", "Sĩ quan hậu cần của Varga, bị bắt tại trại: \"Ông ấy nói cứ ta mất một chiếc là ông ấy đóng hai. Ông ấy thôi nói câu đó từ tháng Mười Một.\""),
            ["mission.c6m09.fragment.title"] = ("Two tanks for one", "Hai đổi một"),
            ["mission.c6m09.name"] = ("Varga's Winter Camp", "Trại mùa đông của Varga"),
            ["mission.c6m10.brief"] = ("Varga's last card is the Frost Monster, a Behemoth bigger than any before, and it is coming for the dam. The brigade must hold the crest, choose its blow, kill the monster, and hold until General Hùng's relief army arrives. The base here must not fall.", "Lá bài cuối của Varga là Quái Vật Băng, chiếc Behemoth lớn hơn mọi chiếc trước đó, và nó đang tiến về con đập. Lữ đoàn phải giữ mặt đập, chọn đòn đánh, hạ con quái vật, và trụ cho tới khi đạo quân cứu viện của tướng Hùng tới nơi. Căn cứ ở đây không được thất thủ."),
            ["mission.c6m10.fragment"] = ("General Hùng's first words on arrival, broadcast to his whole army: \"The Northern Army has saved the dam.\" Colonel Khai's staff heard it too. Nobody said anything.", "Câu đầu tiên của tướng Hùng khi tới nơi, phát cho toàn quân của ông: \"Tập đoàn quân Phương Bắc đã cứu con đập.\" Ban tham mưu của đại tá Khải cũng nghe thấy. Không ai nói gì."),
            ["mission.c6m10.fragment.title"] = ("Relief", "Cứu viện"),
            ["mission.c6m10.name"] = ("Defend the Dam", "Bảo vệ con đập"),
            ["mission.c6s1.brief"] = ("Varga's night raiders are bombing the Ashfield fortress. Diều Hâu wants fourteen of them down before dawn.", "Máy bay đột kích đêm của Varga đang ném bom pháo đài Đồng Tro. Diều Hâu muốn bắn rơi mười bốn chiếc trước bình minh."),
            ["mission.c6s1.fragment"] = ("At dawn Diều Hâu counted the wrecks from the air, then landed and counted them again on foot. Fourteen, both times. He bought the anti-air crews breakfast.", "Lúc bình minh, Diều Hâu đếm xác máy bay từ trên không, rồi hạ cánh đi bộ đếm lại. Cả hai lần đều mười bốn. Anh khao các kíp phòng không bữa sáng."),
            ["mission.c6s1.fragment.title"] = ("Dawn", "Bình minh"),
            ["mission.c6s1.name"] = ("Night Raiders", "Không kích đêm"),
            ["mission.c6s2.brief"] = ("Mai needs to know whether the dam will hold a siege. Get a vehicle onto the power station, the bridge and the ford, and let her engineers look.", "Mai cần biết con đập có chịu nổi một trận vây hãm hay không. Đưa xe tới trạm phát điện, cây cầu và bến lội để công binh của cô quan sát."),
            ["mission.c6s2.fragment"] = ("The engineers found three cracks in the dam, all old, all repaired by Hegemon's own crews. \"They cared about this dam,\" Mai said. \"That makes two of us.\"", "Công binh tìm thấy ba vết nứt trên thân đập, đều cũ, đều đã được chính người của Hegemon sửa. \"Họ quý con đập này,\" Mai nói. \"Vậy là có hai bên cùng quý nó.\""),
            ["mission.c6s2.fragment.title"] = ("Cracks", "Vết nứt"),
            ["mission.c6s2.name"] = ("Survey the Dam", "Khảo sát con đập"),
            ["mission.c7m01.brief"] = ("With Sen's files in hand, the brigade turns towards Skyhold. Quạ Đen's air wing meets us over Frostpeak, coming from the south this time. Bring twelve of them down.", "Cầm trong tay hồ sơ của Sen, lữ đoàn quay mũi về Tầng Mây. Phi đội của Quạ Đen đón đánh ta trên Đỉnh Sương Giá, lần này từ phía nam. Bắn rơi mười hai chiếc."),
            ["mission.c7m01.fragment"] = ("Sen's files, first page: \"Project S.B. Full-scale flight article. Laser, coilguns, field shield. Target date for deployment over the capital: spring.\" It was already autumn.", "Hồ sơ của Sen, trang đầu: \"Dự án S.B. Nguyên mẫu bay cỡ thật. La-de, súng điện từ, khiên trường lực. Ngày dự kiến triển khai trên bầu trời thủ đô: mùa xuân.\" Lúc đó đã là mùa thu."),
            ["mission.c7m01.fragment.title"] = ("Sen's files", "Hồ sơ của Sen"),
            ["mission.c7m01.name"] = ("Crows over the Pass", "Bầy quạ trên đèo"),
            ["mission.c7m02.brief"] = ("Before we hit the air base, Linh wants to see it: the two aprons and the runway. Get a vehicle onto each, under Quạ Đen's nose.", "Trước khi đánh căn cứ không quân, Linh muốn tận mắt thấy nó: hai sân đỗ và đường băng. Đưa xe tới từng nơi, ngay dưới mũi Quạ Đen."),
            ["mission.c7m02.fragment"] = ("The recon team photographed a hangar with its doors welded shut and cooling pipes running into the ground. Sen looked at the photograph for a long time. \"That is it,\" she said.", "Tổ trinh sát chụp được một nhà chứa máy bay cửa bị hàn chết, ống làm lạnh chạy xuống lòng đất. Sen nhìn tấm ảnh rất lâu. \"Chính là nó,\" bà nói."),
            ["mission.c7m02.fragment.title"] = ("The hangar", "Nhà chứa máy bay"),
            ["mission.c7m02.name"] = ("Eyes on Skyhold", "Mắt nhìn Tầng Mây"),
            ["mission.c7m03.brief"] = ("Orlov's old radar on the heights now watches the sky for us, and the village church is our aid station. Quạ Đen wants both gone. Keep one standing for seven minutes.", "Trạm radar cũ của Orlov trên cao điểm giờ canh bầu trời cho ta, còn nhà thờ trong làng là trạm cứu thương. Quạ Đen muốn xóa sổ cả hai. Giữ ít nhất một công trình đứng vững bảy phút."),
            ["mission.c7m03.fragment"] = ("Orlov's radar still had his crew's coffee cups on the console. The brigade's operators kept using them. \"Orlov's cups,\" they called them, with some respect.", "Trạm radar của Orlov vẫn còn những cốc cà phê của kíp trực trên bàn điều khiển. Người của lữ đoàn cứ thế dùng tiếp. Họ gọi đó là \"cốc của Orlov\", với chút kính nể."),
            ["mission.c7m03.fragment.title"] = ("Borrowed eyes", "Đôi mắt đi mượn"),
            ["mission.c7m03.name"] = ("Our Radar Now", "Radar giờ là của ta"),
            ["mission.c7m04.brief"] = ("A night raid on the western apron of Skyhold: Quạ Đen's strike jets are parked in a row. Burn them where they stand.", "Một trận đột kích đêm vào sân đỗ phía tây Tầng Mây: máy bay cường kích của Quạ Đen đang đỗ thành hàng. Đốt chúng ngay tại chỗ."),
            ["mission.c7m04.fragment"] = ("Quạ Đen parked his jets wingtip to wingtip, the way they do at air shows. His ground crew had warned him. He liked the way it looked.", "Quạ Đen cho đỗ máy bay sát cánh nhau, kiểu người ta vẫn làm ở các buổi trình diễn. Tổ kỹ thuật mặt đất đã cảnh báo hắn. Hắn thích trông nó như thế."),
            ["mission.c7m04.fragment.title"] = ("The row", "Hàng máy bay"),
            ["mission.c7m04.name"] = ("Burn the Jets", "Đốt máy bay"),
            ["mission.c7m05.brief"] = ("The welded hangar opened at dawn. Silver Bug is in the air over Skyhold: a saucer with a laser, coilguns and a shield. It is not finished, Sen says. Hurt it badly enough, and it will run.", "Nhà chứa bị hàn cửa đã mở lúc bình minh. Bọ Bạc đang ở trên không phận Tầng Mây: một chiếc đĩa bay mang la-de, súng điện từ và khiên. Sen nói nó chưa hoàn thiện. Đánh nó đủ đau, nó sẽ bỏ chạy."),
            ["mission.c7m05.fragment"] = ("Silver Bug broke off at half strength and flew south at a speed nothing of ours can match. Linh tracked it until it vanished over the desert. Towards the launch site.", "Bọ Bạc tháo chạy khi còn một nửa sức mạnh và bay về phía nam với tốc độ không thứ gì của ta đuổi kịp. Linh theo dấu nó cho tới khi nó biến mất trên sa mạc. Về phía bãi phóng."),
            ["mission.c7m05.fragment.title"] = ("It runs", "Nó bỏ chạy"),
            ["mission.c7m05.name"] = ("Silver Bug", "Bọ Bạc"),
            ["mission.c7m06.brief"] = ("Quạ Đen has hidden long-range SAMs in the fog to shield his air base. Linh has marked three launchers. Hunt them so Diều Hâu can fly.", "Quạ Đen giấu các dàn tên lửa phòng không tầm xa trong sương để che chắn căn cứ. Linh đã đánh dấu ba bệ phóng. Săn chúng để Diều Hâu được bay."),
            ["mission.c7m06.fragment"] = ("With the missile screen gone, Diều Hâu flew over Skyhold at noon and waggled his wings over the control tower. Quạ Đen did not come up. That worried everyone.", "Màn tên lửa bị xóa sổ, Diều Hâu bay qua Tầng Mây giữa trưa và lắc cánh ngay trên tháp điều khiển. Quạ Đen không cất cánh. Điều đó khiến ai cũng lo."),
            ["mission.c7m06.fragment.title"] = ("Clear air", "Bầu trời thông thoáng"),
            ["mission.c7m06.name"] = ("The Missile Screen", "Màn tên lửa"),
            ["mission.c7m07.brief"] = ("Quạ Đen answers with everything he has: wave after wave over our positions round Skyhold. Bring down sixteen.", "Quạ Đen đáp trả bằng tất cả những gì hắn có: từng đợt, từng đợt máy bay lao vào trận địa của ta quanh Tầng Mây. Bắn rơi mười sáu chiếc."),
            ["mission.c7m07.fragment"] = ("Of the sixteen aircraft shot down that day, four were flown by pilots who had trained with Diều Hâu. He went to see the two who survived, in the hospital.", "Trong mười sáu chiếc bị bắn rơi hôm đó, bốn chiếc do những phi công từng học cùng Diều Hâu lái. Anh vào bệnh viện thăm hai người còn sống sót."),
            ["mission.c7m07.fragment.title"] = ("Sixteen", "Mười sáu"),
            ["mission.c7m07.name"] = ("Air Raid", "Không kích"),
            ["mission.c7m08.brief"] = ("Aviation fuel for Diều Hâu's squadron, by road through the pass at night, to the lumber camp airstrip. Three of five tankers must get there.", "Nhiên liệu máy bay cho phi đội của Diều Hâu, theo đường bộ qua đèo trong đêm, tới đường băng dã chiến ở trại gỗ. Năm xe bồn phải tới được ba."),
            ["mission.c7m08.fragment"] = ("The lumber camp airstrip is 700 metres of packed snow. Diều Hâu says it is the best runway on the coast. He also says that about every runway he has landed on.", "Đường băng ở trại gỗ dài 700 mét tuyết nén. Diều Hâu bảo đó là đường băng tốt nhất dải duyên hải. Anh cũng nói thế về mọi đường băng anh từng hạ cánh."),
            ["mission.c7m08.fragment.title"] = ("Airstrip", "Đường băng dã chiến"),
            ["mission.c7m08.name"] = ("Fuel for the Hawks", "Nhiên liệu cho Diều Hâu"),
            ["mission.c7m09.brief"] = ("Quạ Đen's own headquarters, at the east end of the base, ringed with missiles. Level it; the air base will fight on, but without its head.", "Sở chỉ huy riêng của Quạ Đen, ở đầu đông căn cứ, vây kín tên lửa. San phẳng nó; căn cứ không quân sẽ còn kháng cự, nhưng đã mất đầu."),
            ["mission.c7m09.fragment"] = ("In Quạ Đen's quarters: a photograph of two young pilots in front of a trainer aircraft, arms round each other. Diều Hâu took it. He has not said what he did with it.", "Trong phòng của Quạ Đen: một tấm ảnh hai phi công trẻ đứng trước chiếc máy bay huấn luyện, khoác vai nhau. Diều Hâu đã lấy tấm ảnh. Anh chưa nói đã làm gì với nó."),
            ["mission.c7m09.fragment.title"] = ("The photograph", "Tấm ảnh"),
            ["mission.c7m09.name"] = ("Black Crow's Nest", "Tổ Quạ Đen"),
            ["mission.c7m10.brief"] = ("The air base itself. Blind its radars, choose your second blow, bring down Quạ Đen's command airship, shoot his last wave out of the sky, and hold the base against the garrison's last push.", "Chính căn cứ không quân. Làm mù radar, chọn đòn thứ hai, bắn rơi khinh hạm chỉ huy của Quạ Đen, quét sạch đợt máy bay cuối cùng của hắn, rồi giữ căn cứ trước đợt phản kích cuối của quân đồn trú."),
            ["mission.c7m10.fragment"] = ("Diều Hâu shot Quạ Đen down over the runway. He circled until he saw the parachute open, then called in the position for the medics. Quạ Đen was gone by the time they got there.", "Diều Hâu bắn rơi Quạ Đen ngay trên đường băng. Anh bay vòng cho tới khi thấy dù bung, rồi báo tọa độ cho quân y. Lúc họ tới nơi, Quạ Đen đã biến mất."),
            ["mission.c7m10.fragment.title"] = ("Wingmen", "Bay kèm"),
            ["mission.c7m10.name"] = ("Storm Skyhold", "Tấn công Tầng Mây"),
            ["mission.c7s1.brief"] = ("Two trucks are carrying Silver Bug's spare parts off the base in the fog. Sen wants them stopped before they reach the desert. They are marked.", "Hai xe tải đang chở phụ tùng của Bọ Bạc rời căn cứ trong sương. Sen muốn chặn chúng trước khi chúng tới sa mạc. Chúng đã được đánh dấu."),
            ["mission.c7s1.fragment"] = ("The trucks carried six coilgun barrels and a shield emitter. Sen took the emitter apart on the workshop floor and said, very quietly, \"They fixed my mistake.\"", "Các xe tải chở sáu nòng súng điện từ và một bộ phát khiên. Sen tháo bộ phát khiên ra trên sàn xưởng và nói rất khẽ: \"Chúng đã sửa lỗi của tôi.\""),
            ["mission.c7s1.fragment.title"] = ("Coils", "Cuộn dây"),
            ["mission.c7s1.name"] = ("Spare Parts", "Phụ tùng"),
            ["mission.c7s2.brief"] = ("Quạ Đen's parachute came down somewhere in the pass. Linh wants the radar hill, the village and the lumber camp checked before Hegemon finds him first.", "Dù của Quạ Đen rơi xuống đâu đó trên đèo. Linh muốn kiểm tra đồi radar, ngôi làng và trại gỗ trước khi Hegemon tìm ra hắn."),
            ["mission.c7s2.fragment"] = ("The parachute was found at the lumber camp, folded neatly. Next to it, a note in Diều Hâu's old flight school code: \"Not yet.\"", "Chiếc dù được tìm thấy ở trại gỗ, gấp gọn gàng. Bên cạnh là một mẩu giấy viết bằng mật mã cũ của trường bay: \"Chưa đâu.\""),
            ["mission.c7s2.fragment.title"] = ("Gone", "Biệt tăm"),
            ["mission.c7s2.name"] = ("The Crow's Trail", "Dấu vết của Quạ"),
            ["mission.c8m01.brief"] = ("Metro City is the gate to the capital. Take the park, the plaza and the parking lot in the fog, street by street.", "Đô Thành là cửa ngõ vào thủ đô. Chiếm công viên, quảng trường và bãi đỗ xe trong sương mù, từng con phố một."),
            ["mission.c8m01.fragment"] = ("The city's streetlights came on the night we arrived, for the first time in two years. Hegemon had rationed the power. Mai had not.", "Đêm ta tới, đèn đường thành phố bật sáng lần đầu tiên sau hai năm. Hegemon đã cắt điện theo khẩu phần. Mai thì không."),
            ["mission.c8m01.fragment.title"] = ("Streetlights", "Đèn đường"),
            ["mission.c8m01.name"] = ("Into the City", "Vào thành phố"),
            ["mission.c8m02.brief"] = ("The capital sits on a river island. Before General Hùng arrives, Linh wants eyes on the gardens, the palace square and the station.", "Thủ đô nằm trên một hòn đảo giữa sông. Trước khi tướng Hùng tới, Linh muốn quan sát khu vườn, quảng trường cung điện và nhà ga."),
            ["mission.c8m02.fragment"] = ("At the station, the recon team met a patrol of General Hùng's army that was not supposed to be there for three days. Its officer would not say who had sent him.", "Ở nhà ga, tổ trinh sát gặp một toán tuần tra của tướng Hùng, lẽ ra ba ngày nữa mới có mặt. Viên sĩ quan chỉ huy không chịu nói ai đã phái hắn tới."),
            ["mission.c8m02.fragment.title"] = ("Hùng's men", "Người của Hùng"),
            ["mission.c8m02.name"] = ("The Bridges of Lam Thành", "Những cây cầu Lam Thành"),
            ["mission.c8m03.brief"] = ("The city has risen: the resistance holds the plaza, and Aurel's guard has it surrounded. Break the ring before their HQ falls; the besiegers are marked.", "Thành phố đã nổi dậy: quân kháng chiến giữ quảng trường, và vệ binh của Aurel đã vây kín họ. Phá vòng vây trước khi sở chỉ huy của họ thất thủ; quân vây được đánh dấu."),
            ["mission.c8m03.fragment"] = ("It rained all day. The people of the plaza held umbrellas over the wounded while the tanks fought round them. Somebody photographed it; the picture was on every wall by evening.", "Trời mưa cả ngày. Người dân ở quảng trường giương ô che cho thương binh trong khi xe tăng giao chiến quanh họ. Có người chụp lại; tới chiều tối, bức ảnh đã dán trên mọi bức tường."),
            ["mission.c8m03.fragment.title"] = ("Umbrellas", "Những chiếc ô"),
            ["mission.c8m03.name"] = ("The Plaza Uprising", "Khởi nghĩa quảng trường"),
            ["mission.c8m04.brief"] = ("Aurel has ordered the city's towers shelled rather than leave them to us: thousands of people live in them. Keep at least one standing for seven minutes.", "Aurel ra lệnh nã pháo vào các tòa tháp của thành phố chứ không chịu để lại cho ta: hàng nghìn người đang sống trong đó. Giữ ít nhất một tòa đứng vững bảy phút."),
            ["mission.c8m04.fragment"] = ("Aurel's order to his artillery, recovered: \"Deny the enemy the high ground. Civilian occupancy estimate: acceptable.\" Linh read it out on the radio. The gunners stopped firing.", "Lệnh của Aurel gửi pháo binh, thu được: \"Không để địch chiếm điểm cao. Ước tính số dân thường trong tòa nhà: chấp nhận được.\" Linh đọc nó trên sóng phát thanh. Các pháo thủ ngừng bắn."),
            ["mission.c8m04.fragment.title"] = ("Numbers", "Những con số"),
            ["mission.c8m04.name"] = ("The Towers", "Những tòa tháp"),
            ["mission.c8m05.brief"] = ("A missile train is crossing Metro City to its launch siding. When it gets there, a sixty-second countdown starts. Stop it first.", "Một đoàn tàu tên lửa đang băng qua Đô Thành tới đường nhánh phóng. Tới nơi là bắt đầu đếm ngược sáu mươi giây. Phải chặn nó trước."),
            ["mission.c8m05.fragment"] = ("The Doomsday Train's missile carried no warhead. Linh found the reason in its papers: the warhead was being fitted somewhere else. On Silver Bug.", "Tên lửa trên Đoàn Tàu Tận Thế không có đầu đạn. Linh tìm ra lý do trong giấy tờ của nó: đầu đạn đang được lắp ở một nơi khác. Trên Bọ Bạc."),
            ["mission.c8m05.fragment.title"] = ("The warhead", "Đầu đạn"),
            ["mission.c8m05.name"] = ("The Doomsday Train", "Đoàn tàu tận thế"),
            ["mission.c8m06.brief"] = ("A foothold in the capital: the palace square. Aurel's guard wants it back. Hold it in the fog for four minutes.", "Một chỗ đứng chân trong thủ đô: quảng trường cung điện. Vệ binh của Aurel muốn giành lại. Giữ nó trong sương mù bốn phút."),
            ["mission.c8m06.fragment"] = ("The Alliance flag went up over the palace square at 14:10. The Hegemon banner it replaced had been hanging there two years; nobody had ever seen it cleaned.", "Cờ Liên minh được kéo lên trên quảng trường cung điện lúc 14 giờ 10. Lá cờ Hegemon bị thay thế đã treo ở đó hai năm; chưa ai từng thấy nó được giặt."),
            ["mission.c8m06.fragment.title"] = ("The flag", "Lá cờ"),
            ["mission.c8m06.name"] = ("The Palace Square", "Quảng trường cung điện"),
            ["mission.c8m07.brief"] = ("Three of Aurel's commissars are holding the city garrison together from command cars, moving between districts in the storm. Hunt them down; they are marked.", "Ba chính ủy của Aurel đang giữ cho quân đồn trú thành phố khỏi tan rã, di chuyển giữa các quận bằng xe chỉ huy trong cơn bão. Săn lùng họ; họ đã được đánh dấu."),
            ["mission.c8m07.fragment"] = ("Each commissar carried a copy of the contract that gave Hegemon the coast. Clause 41: \"In the event of unrest, the contractor may take such measures as it sees fit.\" Aurel had seen fit.", "Mỗi chính ủy mang theo một bản sao hợp đồng trao dải duyên hải cho Hegemon. Điều 41: \"Trường hợp có bất ổn, nhà thầu được áp dụng mọi biện pháp mà mình thấy phù hợp.\" Aurel đã thấy phù hợp."),
            ["mission.c8m07.fragment.title"] = ("Contracts", "Những bản hợp đồng"),
            ["mission.c8m07.name"] = ("The Commissars", "Các chính ủy"),
            ["mission.c8m08.brief"] = ("The families sheltering in the palace have to get out before the final battle: six trucks across the west bridge, one every few seconds. Four must make it.", "Các gia đình đang trú trong cung điện phải ra ngoài trước trận quyết chiến: sáu xe tải qua cầu phía tây, cứ vài giây một chiếc. Phải thoát được bốn xe."),
            ["mission.c8m08.fragment"] = ("General Hùng offered to take the evacuees to his own camp. Colonel Khai said the trucks would go to ours. Hùng laughed, and said he understood. He did.", "Tướng Hùng đề nghị đưa những người sơ tán về trại của ông. Đại tá Khải nói các xe sẽ về trại của ta. Hùng bật cười, bảo ông hiểu. Và ông hiểu thật."),
            ["mission.c8m08.fragment.title"] = ("The west bridge", "Cầu phía tây"),
            ["mission.c8m08.name"] = ("Out of the Palace", "Rời cung điện"),
            ["mission.c8m09.brief"] = ("Aurel speaks to the whole country every night from the radar dome by the palace. Tonight he will not. Destroy it.", "Đêm nào Aurel cũng nói chuyện với cả nước từ vòm radar cạnh cung điện. Đêm nay thì không. Phá hủy nó."),
            ["mission.c8m09.fragment"] = ("Aurel's last broadcast from the capital was cut off mid-sentence: \"The Protectorate will always—\" Linh has the tape. She plays it when anyone needs cheering up.", "Buổi phát sóng cuối cùng của Aurel ở thủ đô bị cắt ngang giữa câu: \"Chính quyền Bảo hộ sẽ mãi mãi—\" Linh giữ cuộn băng. Cô bật nó mỗi khi có ai cần vui lên."),
            ["mission.c8m09.fragment.title"] = ("The last broadcast", "Buổi phát sóng cuối cùng"),
            ["mission.c8m09.name"] = ("Silence the Broadcast", "Dập tắt đài phát"),
            ["mission.c8m10.brief"] = ("Lam Thành, with General Hùng's army and his base beside us. Take the bridgeheads, choose your blow, storm the palace, and the capital is free. Linh has one more thing to say before we go: watch General Hùng.", "Lam Thành, với đạo quân và căn cứ của tướng Hùng bên cạnh. Chiếm các đầu cầu, chọn đòn đánh, đánh chiếm cung điện, và thủ đô sẽ được tự do. Trước khi xuất phát, Linh còn một điều muốn nói: hãy để mắt tới tướng Hùng."),
            ["mission.c8m10.fragment"] = ("Hùng's price, found in Aurel's safe: the capital, the ports and the title \"Protector\". Aurel had agreed to all three. He had no intention of honouring any of them.", "Cái giá của Hùng, tìm thấy trong két sắt của Aurel: thủ đô, các bến cảng và danh hiệu \"Người Bảo hộ\". Aurel đồng ý cả ba. Hắn chưa từng định giữ lời điều nào."),
            ["mission.c8m10.fragment.title"] = ("The price", "Cái giá"),
            ["mission.c8m10.name"] = ("Liberate the Capital", "Giải phóng thủ đô"),
            ["mission.c8s1.brief"] = ("Linh has intercepted letters between General Hùng and someone in Metro City. She wants to see the three drop points for herself, quietly.", "Linh đã chặn được những bức thư giữa tướng Hùng và một người nào đó ở Đô Thành. Cô muốn tự mình xem ba điểm trao thư, một cách lặng lẽ."),
            ["mission.c8s1.fragment"] = ("Linh's report to Colonel Khai, handwritten, one copy: \"Hùng is talking to Aurel. I cannot prove it yet. I am sure.\" Khai read it twice and locked it in his desk.", "Báo cáo của Linh gửi đại tá Khải, viết tay, một bản duy nhất: \"Hùng đang liên lạc với Aurel. Tôi chưa chứng minh được. Nhưng tôi chắc chắn.\" Khải đọc hai lần rồi khóa nó vào ngăn bàn."),
            ["mission.c8s1.fragment.title"] = ("Linh's report", "Báo cáo của Linh"),
            ["mission.c8s1.name"] = ("The Letters", "Những bức thư"),
            ["mission.c8s2.brief"] = ("Aurel's guard helicopters are hunting the resistance over the rooftops in the storm. Fourteen of them, down.", "Trực thăng vệ binh của Aurel đang săn quân kháng chiến trên các mái nhà giữa cơn bão. Mười bốn chiếc, bắn rơi hết."),
            ["mission.c8s2.fragment"] = ("The resistance lit fires on the rooftops to mark the helicopters for our gunners. Diều Hâu said it was the prettiest city he had ever fought over.", "Quân kháng chiến đốt lửa trên các mái nhà để đánh dấu trực thăng cho pháo thủ của ta. Diều Hâu bảo đó là thành phố đẹp nhất anh từng chiến đấu trên bầu trời của nó."),
            ["mission.c8s2.fragment.title"] = ("Rooftops", "Những mái nhà"),
            ["mission.c8s2.name"] = ("Storm over the Capital", "Bão trên thủ đô"),
            ["mission.c9m01.brief"] = ("The road to the launch site runs through Dunebreak again, from the south this time. Varga's last armour holds the refinery. Take the oasis, the refinery and the oil field.", "Con đường tới bãi phóng lại đi qua Đồi Cát, lần này từ phía nam. Toán thiết giáp cuối cùng của Varga giữ nhà máy lọc dầu. Chiếm ốc đảo, nhà máy và mỏ dầu."),
            ["mission.c9m01.fragment"] = ("The refinery the brigade burned in chapter two was running again. Hegemon had rebuilt it in four months. The workers had rebuilt it, Mai corrected. Hegemon had watched.", "Nhà máy lọc dầu lữ đoàn đốt ở chương hai đã chạy lại. Hegemon dựng lại nó trong bốn tháng. Mai sửa lại: công nhân dựng lại nó. Hegemon chỉ đứng nhìn."),
            ["mission.c9m01.fragment.title"] = ("The refinery again", "Lại nhà máy lọc dầu"),
            ["mission.c9m01.name"] = ("Back to Dunebreak", "Trở lại Đồi Cát"),
            ["mission.c9m02.brief"] = ("Kessler runs the launch site's rail lines and supply dumps from a base at its northern gate, mined to the teeth. Level his HQ.", "Kessler điều hành đường ray và kho tiếp tế của bãi phóng từ một căn cứ ở cổng bắc, rải mìn dày đặc. San phẳng sở chỉ huy của hắn."),
            ["mission.c9m02.fragment"] = ("Kessler surrendered at 16:00 exactly, on the minute, with his logbook under his arm. His last entry: \"Enemy arrived on schedule.\"", "Kessler đầu hàng đúng 16 giờ, không sai một phút, kẹp cuốn sổ nhật ký dưới nách. Dòng cuối: \"Địch tới đúng lịch.\""),
            ["mission.c9m02.fragment.title"] = ("On time", "Đúng giờ"),
            ["mission.c9m02.name"] = ("Kessler's Last Timetable", "Thời gian biểu cuối cùng của Kessler"),
            ["mission.c9m03.brief"] = ("Varga's final camp, in the dunes where he first built the Behemoth. Every anti-tank gun he has left, and every tank. Level his HQ.", "Trại cuối cùng của Varga, giữa những đồi cát nơi hắn chế tạo chiếc Behemoth đầu tiên. Mọi khẩu pháo chống tăng còn lại, và mọi chiếc xe tăng. San phẳng sở chỉ huy của hắn."),
            ["mission.c9m03.fragment"] = ("Varga did not run this time. He walked out of his HQ, looked at the burning yard, and asked Mai whether she still had the rear plates of hull number one. She said yes.", "Lần này Varga không chạy. Hắn bước ra khỏi sở chỉ huy, nhìn xưởng đang cháy, rồi hỏi Mai cô còn giữ các tấm giáp sau của thân tàu số một không. Cô bảo còn."),
            ["mission.c9m03.fragment.title"] = ("The machines", "Những cỗ máy"),
            ["mission.c9m03.name"] = ("The Last Behemoth Yard", "Xưởng Behemoth cuối cùng"),
            ["mission.c9m04.brief"] = ("Orlov has taken the southern end of the launch site and filled it with guns. From the north this time, break his line and level his HQ.", "Orlov chiếm đầu nam bãi phóng và lấp kín nó bằng pháo. Lần này từ phía bắc, chọc thủng tuyến của hắn và san phẳng sở chỉ huy."),
            ["mission.c9m04.fragment"] = ("Orlov, taken alive, was asked about the word in his notebook. \"Why?\" he said. \"Why I never came closer. Now I have. It is worse.\"", "Orlov bị bắt sống, được hỏi về chữ cuối trong sổ tay. \"Tại sao ư?\" hắn nói. \"Tại sao ta chưa bao giờ tới gần hơn. Giờ thì ta tới rồi. Còn tệ hơn.\""),
            ["mission.c9m04.fragment.title"] = ("The answer", "Câu trả lời"),
            ["mission.c9m04.name"] = ("Orlov's Last Line", "Tuyến cuối của Orlov"),
            ["mission.c9m05.brief"] = ("The second Silver Bug, the one that ran from Skyhold, repaired and armed, is over Dunebreak. This time it does not run. Bring it down.", "Chiếc Bọ Bạc thứ hai, chiếc từng chạy khỏi Tầng Mây, đã được sửa và vũ trang, đang lơ lửng trên Đồi Cát. Lần này nó không chạy. Bắn rơi nó."),
            ["mission.c9m05.fragment"] = ("In the wreck, Sen found the serial plate: \"S.B. 02.\" \"Then there is a 01,\" she said. \"And 01 is the complete one.\"", "Trong xác máy, Sen tìm thấy tấm biển số hiệu: \"S.B. 02.\" \"Vậy là còn một chiếc 01,\" bà nói. \"Và 01 là chiếc hoàn chỉnh.\""),
            ["mission.c9m05.fragment.title"] = ("Two", "Hai chiếc"),
            ["mission.c9m05.name"] = ("Silver Sky", "Bầu trời bạc"),
            ["mission.c9m06.brief"] = ("Quạ Đen has come back from the pass, and he has brought what is left of Hegemon's air force to the launch site. Level his base at night.", "Quạ Đen đã trở về từ đèo, mang theo tàn quân không lực Hegemon tới bãi phóng. San phẳng căn cứ của hắn trong đêm."),
            ["mission.c9m06.fragment"] = ("When his base fell, Quạ Đen called Diều Hâu on the old flight school frequency. \"Now,\" he said, and landed his helicopter in front of our lines with his hands up.", "Khi căn cứ thất thủ, Quạ Đen gọi Diều Hâu trên tần số cũ của trường bay. \"Giờ thì được rồi,\" hắn nói, rồi hạ trực thăng trước trận tuyến của ta, hai tay giơ cao."),
            ["mission.c9m06.fragment.title"] = ("Not yet", "Chưa đâu"),
            ["mission.c9m06.name"] = ("The Crow Returns", "Quạ Đen trở lại"),
            ["mission.c9m07.brief"] = ("Silver Bug's reactor fuel is travelling to the launch site in three guarded trucks. Linh has marked them. Stop every one.", "Nhiên liệu lò phản ứng của Bọ Bạc đang được chở tới bãi phóng trên ba xe tải có hộ tống. Linh đã đánh dấu chúng. Chặn từng chiếc."),
            ["mission.c9m07.fragment"] = ("Sen, on the reactor fuel: \"Without it, the complete Bug can fly for an hour. With it, for a year.\" After this afternoon, it had an hour.", "Sen nói về nhiên liệu lò phản ứng: \"Không có nó, Bọ Bạc hoàn chỉnh bay được một giờ. Có nó, bay được một năm.\" Sau buổi chiều hôm đó, nó chỉ còn một giờ."),
            ["mission.c9m07.fragment.title"] = ("Reactor", "Lò phản ứng"),
            ["mission.c9m07.name"] = ("Fuel for the Bug", "Nhiên liệu cho Bọ Bạc"),
            ["mission.c9m08.brief"] = ("Four radar stations guide Silver Bug off its pad. In the sandstorm, destroy all four.", "Bốn trạm radar dẫn đường cho Bọ Bạc rời bệ phóng. Giữa cơn bão cát, phá hủy cả bốn."),
            ["mission.c9m08.fragment"] = ("With its radars gone, the complete Bug would have to be launched by hand. Sen knew the one man at the site who could do it: Aurel.", "Mất hết radar, chiếc Bọ Bạc hoàn chỉnh sẽ phải phóng bằng tay. Sen biết người duy nhất ở bãi phóng làm được việc đó: Aurel."),
            ["mission.c9m08.fragment.title"] = ("Manual", "Điều khiển tay"),
            ["mission.c9m08.name"] = ("Blind the Launch Site", "Làm mù bãi phóng"),
            ["mission.c9m09.brief"] = ("While the brigade gathers for the final battle, Aurel throws his guard at the refinery, our supply depot now. Hold it for four minutes.", "Trong khi lữ đoàn tập kết cho trận cuối, Aurel tung vệ binh vào nhà máy lọc dầu, giờ là kho tiếp tế của ta. Giữ nó bốn phút."),
            ["mission.c9m09.fragment"] = ("The night before the last battle, Colonel Khai walked the lines and spoke to every crew. He said the same thing to all of them: \"Tomorrow, we go home.\"", "Đêm trước trận cuối, đại tá Khải đi dọc trận tuyến và nói chuyện với từng kíp xe. Ông nói với ai cũng một câu: \"Ngày mai, ta về nhà.\""),
            ["mission.c9m09.fragment.title"] = ("Eve", "Đêm trước"),
            ["mission.c9m09.name"] = ("The Refinery Rearguard", "Hậu vệ nhà máy lọc dầu"),
            ["mission.c9m10.brief"] = ("The last battle. Take the propellant farm, choose your blow, take the assembly building, destroy Aurel's command vehicle, hold the launch pad, and when Silver Bug rises in its complete form, bring it down on its own pad.", "Trận cuối cùng. Chiếm khu nhiên liệu, chọn đòn đánh, chiếm nhà lắp ráp, tiêu diệt xe chỉ huy của Aurel, giữ bệ phóng, và khi Bọ Bạc cất cánh trong hình dạng hoàn chỉnh, bắn rơi nó ngay trên bệ phóng của nó."),
            ["mission.c9m10.fragment"] = ("Silver Bug came down on its own pad at 17:42. The brigade's radio log for the next minute holds no orders, only people cheering, and one voice, Colonel Khai's, saying \"Thank you.\"", "Bọ Bạc rơi xuống ngay trên bệ phóng lúc 17 giờ 42. Sổ ghi bộ đàm của lữ đoàn trong phút tiếp theo không có mệnh lệnh nào, chỉ có tiếng người reo hò, và một giọng nói, của đại tá Khải: \"Cảm ơn.\""),
            ["mission.c9m10.fragment.title"] = ("Clear sky", "Bầu trời trong"),
            ["mission.c9m10.name"] = ("Silver Sky Falls", "Bầu trời bạc sụp đổ"),
            ["mission.c9s1.brief"] = ("Sen needs to see the launch pad, the assembly building and the propellant farm before the last battle. In the sandstorm, from the north.", "Sen cần tận mắt thấy bệ phóng, nhà lắp ráp và khu nhiên liệu trước trận cuối. Giữa cơn bão cát, từ phía bắc."),
            ["mission.c9s1.fragment"] = ("Sen drew the plan of the launch site from memory on the back of a map. Linh checked it against the recon photographs. It was right to the metre.", "Sen vẽ sơ đồ bãi phóng theo trí nhớ lên mặt sau một tấm bản đồ. Linh đối chiếu với ảnh trinh sát. Nó chính xác tới từng mét."),
            ["mission.c9s1.fragment.title"] = ("Sen's plan", "Kế hoạch của Sen"),
            ["mission.c9s1.name"] = ("The Pad", "Bệ phóng"),
            ["mission.c9s2.brief"] = ("What is left of Hegemon's air force is coming over the dunes for the brigade's supply lines. Sixteen of them, down, in the sandstorm.", "Những gì còn lại của không lực Hegemon đang lao qua các đồi cát nhắm vào đường tiếp tế của lữ đoàn. Mười sáu chiếc, bắn rơi hết, giữa cơn bão cát."),
            ["mission.c9s2.fragment"] = ("After this afternoon, Hegemon had no aircraft left on the coast. Diều Hâu flew home low over the dunes and did a barrel roll nobody had authorised.", "Sau buổi chiều hôm đó, Hegemon không còn chiếc máy bay nào trên dải duyên hải. Diều Hâu bay về sát ngọn đồi cát và làm một cú lộn vòng chẳng ai cho phép."),
            ["mission.c9s2.fragment.title"] = ("Empty sky", "Bầu trời trống"),
            ["mission.c9s2.name"] = ("The Last Air Wing", "Phi đội cuối cùng"),
            ["mission.c4m11.brief"] = ("Ironport is ours, but Kessler got out by sea. He is aboard Leviathan, his battleship, off Lighthouse Bay, and he means to shell the coast until we give the port back. Take the lighthouse to see his fleet, man the old coastal batteries, and sink it before it runs for open sea.", "Ironport đã về tay ta, nhưng Kessler thoát được bằng đường biển. Hắn đang ở trên Leviathan, chiến hạm của hắn, ngoài khơi Vịnh Hải Đăng, và định nã pháo vào bờ cho tới khi ta trả lại bến cảng. Chiếm ngọn hải đăng để thấy hạm đội của hắn, dùng các trận địa pháo bờ biển cũ, và đánh chìm nó trước khi nó chạy ra khơi."),
            ["mission.c4m11.fragment"] = ("Divers brought up Leviathan's bridge clock a month later. It had stopped at 16:42, the minute the second magazine went. Kessler's last order in the log, in his own hand: \"Record the time.\"", "Một tháng sau, thợ lặn vớt được chiếc đồng hồ trên cầu chỉ huy của Leviathan. Nó dừng ở 16 giờ 42, đúng phút kho đạn thứ hai phát nổ. Mệnh lệnh cuối cùng trong sổ, chữ của chính Kessler: \"Ghi lại thời gian.\""),
            ["mission.c4m11.fragment.title"] = ("The timetable", "Thời gian biểu"),
            ["mission.c4m11.name"] = ("Leviathan", "Leviathan"),
            ["radio.alliedStrikes"] = ("Diều Hâu here: the air corridor is open. Strikes on call, every minute.", "Diều Hâu đây: hành lang bay đã mở. Không kích theo yêu cầu, mỗi phút một lượt."),
            ["radio.aurel.c7m05.2"] = ("A field test, Colonel. Thank you for volunteering.", "Một cuộc thử nghiệm thực địa thôi, đại tá. Cảm ơn ông đã tình nguyện."),
            ["radio.aurel.c8m01.1"] = ("Welcome to my city, Colonel. Please do not scratch the paintwork.", "Chào mừng tới thành phố của tôi, đại tá. Làm ơn đừng làm xước lớp sơn."),
            ["radio.aurel.c8m09.1"] = ("Everyone has a price, Colonel.", "Ai cũng có giá, đại tá."),
            ["radio.aurel.c9m05.2"] = ("Silver Bug is not a weapon, Colonel. It is a contract nobody can refuse.", "Bọ Bạc không phải vũ khí, đại tá. Nó là một bản hợp đồng không ai từ chối nổi."),
            ["radio.aurel.c9m10.s4"] = ("You are standing on my balance sheet, Colonel.", "Ông đang đứng trên bảng cân đối của tôi đấy, đại tá."),
            ["radio.aurel.c9m10.s6"] = ("Launch. Manually, since you insist.", "Phóng. Bằng tay, vì ông cứ nhất định như thế."),
            ["radio.aurel.defeat"] = ("This was not in the forecast.", "Chuyện này không có trong dự báo."),
            ["radio.aurel.taunt.1"] = ("Your brigade is a rounding error on my balance sheet.", "Lữ đoàn của ông chỉ là sai số làm tròn trên bảng cân đối của tôi."),
            ["radio.aurel.taunt.2"] = ("Everyone has a price, Colonel. General Hùng had his.", "Ai cũng có giá, đại tá. Tướng Hùng cũng có giá của ông ta."),
            ["radio.aurel.taunt.3"] = ("Silver Bug is not a weapon. It is a contract nobody can refuse.", "Bọ Bạc không phải vũ khí. Nó là một bản hợp đồng không ai từ chối nổi."),
            ["radio.betrayal"] = ("The allied commander has turned on us: their units are firing on ours!", "Chỉ huy đồng minh đã trở mặt: quân của họ đang bắn vào ta!"),
            ["radio.bossFled"] = ("It is breaking off! Let it go, we have what we came for.", "Nó đang tháo chạy! Để nó đi, ta đạt được mục tiêu rồi."),
            ["radio.dieuhau.c1m01.2"] = ("Diều Hâu overhead. Beach exit is ours, I can see the whole bay from here!", "Diều Hâu trên đầu các anh đây. Cửa ra bãi biển là của ta rồi, từ đây tôi thấy cả vịnh!"),
            ["radio.dieuhau.c1m05.1"] = ("Something big on the water, Colonel. Bigger than a boat, faster than a tank.", "Có thứ gì to lắm trên mặt nước, đại tá. To hơn xuồng, nhanh hơn xe tăng."),
            ["radio.dieuhau.c2s2.1"] = ("Helicopters, low and slow. My favourite kind.", "Trực thăng, bay thấp và chậm. Loại tôi khoái nhất."),
            ["radio.dieuhau.c3m05.1"] = ("Big bird, big target. Keep the launchers moving under it.", "Chim to, bia to. Cho các bệ phóng di chuyển liên tục dưới nó."),
            ["radio.dieuhau.c3m05.3"] = ("Iron Bird is down! Somebody owes me a drink.", "Chim Sắt rơi rồi! Có ai đó nợ tôi một chầu đấy."),
            ["radio.dieuhau.c5m07.1"] = ("Drones, lots of them. Keep the anti-air moving under the trees.", "Drone, nhiều lắm. Cho phòng không di chuyển liên tục dưới tán cây."),
            ["radio.dieuhau.c6m05.1"] = ("It flies above my ceiling at night. The SAMs will have to do this one.", "Ban đêm nó bay cao hơn trần bay của tôi. Lần này phải nhờ tên lửa phòng không rồi."),
            ["radio.dieuhau.c6m05.2"] = ("The ghost is down. Sleep well tonight, everyone.", "Bóng ma rơi rồi. Đêm nay mọi người ngủ ngon nhé."),
            ["radio.dieuhau.c6s1.1"] = ("They come in low from the north. Let them.", "Chúng bay thấp tới từ phía bắc. Cứ để chúng tới."),
            ["radio.dieuhau.c7m01.2"] = ("Still faster than you, Crow.", "Vẫn nhanh hơn mày, Quạ ạ."),
            ["radio.dieuhau.c7m04.1"] = ("They are parked in a line. He always did like to show off.", "Chúng đỗ thành một hàng. Hắn lúc nào cũng thích khoe mẽ."),
            ["radio.dieuhau.c7m06.1"] = ("Get those launchers and I buy the beer.", "Diệt được mấy bệ phóng đó thì tôi khao bia."),
            ["radio.dieuhau.c7m08.1"] = ("No fuel, no air cover. Bring me my fuel.", "Không có nhiên liệu thì không có yểm trợ trên không. Mang nhiên liệu cho tôi."),
            ["radio.dieuhau.c7m10.s4"] = ("That's him in the lead jet. He's mine, everyone. Keep the others off me.", "Hắn ở chiếc dẫn đầu. Hắn là của tôi, mọi người. Giữ mấy chiếc kia khỏi bám tôi."),
            ["radio.dieuhau.c8s2.1"] = ("Watch the fires on the roofs. Each one is a helicopter.", "Nhìn những đốm lửa trên mái nhà. Mỗi đốm là một chiếc trực thăng."),
            ["radio.dieuhau.c9m06.2"] = ("For the old days, Crow.", "Vì ngày xưa, Quạ ạ."),
            ["radio.dieuhau.c9s2.1"] = ("The last of them. Let's make it quick.", "Tốp cuối cùng rồi. Làm nhanh gọn thôi."),
            ["radio.enemyWeakened"] = ("Their supply is burning. They will feel that for the rest of the day.", "Kho tiếp tế của chúng đang cháy. Cả ngày hôm nay chúng sẽ thấm đòn."),
            ["radio.hung.c6m10.s4"] = ("Khải! Hùng here, the Northern Army is on the road. Hold on, we are coming.", "Khải! Hùng đây, Tập đoàn quân Phương Bắc đang trên đường. Cố lên, chúng tôi đang tới."),
            ["radio.hung.c8m10.s1"] = ("The Northern Army takes the left. Khải, take the right, and we meet at the palace.", "Tập đoàn quân Phương Bắc đánh cánh trái. Khải, cánh phải, ta gặp nhau ở cung điện."),
            ["radio.hung.c8m10.s4"] = ("I am sorry, Khải. The coast needs a protector. It was never going to be you.", "Tôi xin lỗi, Khải. Dải duyên hải cần một người bảo hộ. Người đó chưa bao giờ là anh."),
            ["radio.kessler.c4m01.1"] = ("You are four minutes behind schedule, Colonel.", "Ngươi đang trễ bốn phút so với lịch, đại tá."),
            ["radio.kessler.c4m05.1"] = ("The train leaves on time, Colonel. It always does.", "Tàu chạy đúng giờ, đại tá. Xưa nay vẫn thế."),
            ["radio.kessler.c4m05.3"] = ("Cancel the timetable.", "Hủy lịch trình."),
            ["radio.kessler.c4m09.1"] = ("Every road here is mined. I checked.", "Mọi con đường ở đây đều có mìn. Ta đã kiểm tra rồi."),
            ["radio.kessler.c4m09.2"] = ("Evacuate the quarters. By sea.", "Sơ tán tổng hành dinh. Bằng đường biển."),
            ["radio.kessler.c4m10.s4"] = ("Tempest, clear the docks. On schedule.", "Tempest, dọn sạch bến tàu. Đúng lịch."),
            ["radio.kessler.c9m02.1"] = ("The next train leaves on time. With or without you under it.", "Chuyến tàu sau sẽ chạy đúng giờ. Dù có ngươi nằm dưới bánh hay không."),
            ["radio.kessler.c9m02.2"] = ("Cancel the timetable. All of it.", "Hủy lịch trình. Toàn bộ."),
            ["radio.kessler.defeat"] = ("Cancel the timetable. Evacuate the port by sea.", "Hủy lịch trình. Sơ tán bến cảng bằng đường biển."),
            ["radio.kessler.taunt.1"] = ("You are four minutes behind schedule, Colonel.", "Ngươi đang trễ bốn phút so với lịch, đại tá."),
            ["radio.kessler.taunt.2"] = ("Every road here is mined. I checked.", "Mọi con đường ở đây đều có mìn. Ta đã kiểm tra rồi."),
            ["radio.kessler.taunt.3"] = ("The next train leaves on time. With or without you under it.", "Chuyến tàu sau sẽ chạy đúng giờ. Dù có ngươi nằm dưới bánh hay không."),
            ["radio.khai.c1m01.1"] = ("Brigade, this is Khải. Off the sand and up the draw. Nobody stops on the beach.", "Lữ đoàn, Khải đây. Rời bãi cát, lên dốc. Không ai được dừng lại trên bãi biển."),
            ["radio.khai.c1m01.3"] = ("Beachhead secured. Now we find somewhere to build.", "Đầu cầu đã an toàn. Giờ tìm chỗ dựng căn cứ."),
            ["radio.khai.c1m02.2"] = ("Radar down. Tell the boats they can come in.", "Radar đã sập. Báo các xuồng vào bờ được rồi."),
            ["radio.khai.c1m03.1"] = ("Three objectives, light resistance. Show me what the brigade can do.", "Ba cứ điểm, địch kháng cự yếu. Cho tôi xem lữ đoàn làm được gì."),
            ["radio.khai.c1m05.2"] = ("There it is. Hit it before it reaches the draw.", "Nó đây rồi. Đánh nó trước khi nó lên tới con dốc."),
            ["radio.khai.c1m05.3"] = ("The tide goes out for them tonight.", "Đêm nay thủy triều rút về phía chúng."),
            ["radio.khai.c1m06.1"] = ("The convoy moves when you move. Stay with it.", "Đoàn xe đi khi các anh đi. Bám sát nó."),
            ["radio.khai.c1m07.1"] = ("Silos and water tower. Nothing else matters today.", "Kho lúa và tháp nước. Hôm nay không có gì quan trọng hơn."),
            ["radio.khai.c1m08.1"] = ("The fortress watches this road. Take the town and the depots, and it watches nothing.", "Pháo đài canh con đường này. Chiếm thị trấn và các kho, nó sẽ chẳng còn gì để canh."),
            ["radio.khai.c1m09.1"] = ("No shells, no siege. Keep the trucks moving.", "Không có đạn thì không vây được. Giữ cho đoàn xe chạy."),
            ["radio.khai.c1m10.1"] = ("This is what we landed for. The fortress falls today.", "Ta đổ bộ là vì hôm nay. Pháo đài phải thất thủ."),
            ["radio.khai.c1m10.2"] = ("Ashfield is ours. Chapter one of a long book, Brigade.", "Đồng Tro là của ta. Chương đầu của một cuốn sách dài, Lữ đoàn ạ."),
            ["radio.khai.c1m10.s1"] = ("Fuel depot first. Light it up and their tanks go hungry.", "Kho nhiên liệu trước. Đốt nó đi, xe tăng của chúng sẽ đói."),
            ["radio.khai.c1m10.s4"] = ("The garrison is coming back out of the kilns. Hold where you stand.", "Quân đồn trú đang tràn ra từ các lò nung. Giữ nguyên vị trí."),
            ["radio.khai.c2m01.1"] = ("Five minutes. Dig in round the pumps and let them come.", "Năm phút. Bám quanh các giàn bơm và để chúng tới."),
            ["radio.khai.c2m03.1"] = ("Lights off, engines low. Bring them through.", "Tắt đèn, hạ ga. Đưa họ qua."),
            ["radio.khai.c2m04.1"] = ("Five stations. Every one burns.", "Năm trạm. Trạm nào cũng phải cháy."),
            ["radio.khai.c2m07.1"] = ("They held for two years. We can hold for them tonight.", "Họ giữ được hai năm. Đêm nay ta giữ cho họ."),
            ["radio.khai.c2m08.1"] = ("Four minutes in the yard. Do not chase them out.", "Bốn phút trong sân. Đừng đuổi theo chúng ra ngoài."),
            ["radio.khai.c2m09.2"] = ("Neither do I.", "Tôi cũng thế."),
            ["radio.khai.c2m10.1"] = ("The refinery burns today, Brigade. Everything inside it too.", "Hôm nay nhà máy lọc dầu phải cháy, Lữ đoàn. Cả những gì bên trong nó."),
            ["radio.khai.c2m10.2"] = ("Varga is running out of fuel, and out of monsters.", "Varga đang cạn dầu, và cạn cả quái vật."),
            ["radio.khai.c2m10.s1"] = ("Oil field and oasis first. Then we choose.", "Mỏ dầu và ốc đảo trước. Rồi ta sẽ chọn."),
            ["radio.khai.c3m01.2"] = ("Keep moving. Coordinates that move are harder to hit.", "Cứ di chuyển. Tọa độ biết chạy thì khó bắn trúng hơn."),
            ["radio.khai.c3m03.1"] = ("We hold the village. They come to us, in the fog.", "Ta giữ ngôi làng. Chúng sẽ tới chỗ ta, trong sương."),
            ["radio.khai.c3m07.1"] = ("Civilians in the cabins. They are the objective.", "Dân thường trong các căn nhà gỗ. Họ chính là mục tiêu."),
            ["radio.khai.c3m10.1"] = ("The line breaks today, or the winter wins. Move.", "Hôm nay tuyến phải vỡ, không thì mùa đông thắng. Tiến lên."),
            ["radio.khai.c3m10.2"] = ("The highlands are open. Act one is done, Brigade.", "Cao nguyên đã mở. Hồi thứ nhất khép lại rồi, Lữ đoàn."),
            ["radio.khai.c3m10.s1"] = ("The hill radar first. Without it, his guns fire blind.", "Radar trên đồi trước. Mất nó, pháo của hắn bắn mù."),
            ["radio.khai.c4m01.2"] = ("Then we will make up the time.", "Vậy thì ta sẽ bù lại số phút đó."),
            ["radio.khai.c4m03.1"] = ("Fog is cover. Use it, and stay with the trucks.", "Sương mù là chỗ ẩn nấp. Tận dụng nó, và bám sát đoàn xe."),
            ["radio.khai.c4m05.2"] = ("Everything on the train. Now.", "Dồn hết vào đoàn tàu. Ngay."),
            ["radio.khai.c4m07.1"] = ("The factories are the objective. Everything else is noise.", "Khu nhà máy là mục tiêu. Mọi thứ khác chỉ là tiếng ồn."),
            ["radio.khai.c4m10.1"] = ("The port, Brigade. All of it, by tonight.", "Bến cảng, Lữ đoàn. Toàn bộ, trước đêm nay."),
            ["radio.khai.c4m10.2"] = ("Ironport is free. Kessler's timetable is ours now.", "Cảng Thép tự do rồi. Thời gian biểu của Kessler giờ thuộc về ta."),
            ["radio.khai.c4m10.s1"] = ("The rail yard first: it is the key to the rest.", "Bãi đường sắt trước: nó là chìa khóa cho phần còn lại."),
            ["radio.khai.c5m03.1"] = ("Eyes up. The fog does not hide you from drones.", "Nhìn lên trời. Sương mù không che được các anh khỏi drone đâu."),
            ["radio.khai.c5m05.2"] = ("Ground guns on it. Keep the aircraft home.", "Pháo mặt đất dồn vào nó. Máy bay ở nhà."),
            ["radio.khai.c5m06.1"] = ("Walls first, then the HQ. The guns do the talking.", "Tường trước, rồi tới sở chỉ huy. Để pháo nói chuyện."),
            ["radio.khai.c5m10.1"] = ("The mothership falls today. Everything else is on the way to it.", "Hôm nay tàu mẹ phải rơi. Mọi thứ khác chỉ là đường tới nó."),
            ["radio.khai.c5m10.2"] = ("Sen is surrendering, Colonel? …Bring her in. Carefully.", "Sen ra hàng à? …Đưa bà ấy về. Cẩn thận."),
            ["radio.khai.c5m10.s1"] = ("The causeways first. They are the only roads over the lava.", "Các đường đắp trước. Đó là những con đường duy nhất vượt qua dung nham."),
            ["radio.khai.c6m01.2"] = ("It was never yours. Hold the walls.", "Nó chưa bao giờ là của ngươi. Giữ tường thành."),
            ["radio.khai.c6m02.1"] = ("Nobody is left behind. Hold the lake.", "Không bỏ lại ai. Giữ hồ băng."),
            ["radio.khai.c6m06.1"] = ("The bridge, four minutes. Nobody crosses.", "Cây cầu, bốn phút. Không ai được qua."),
            ["radio.khai.c6m07.1"] = ("Break the ring. Their HQ first, everything else second.", "Phá vòng vây. Sở chỉ huy của họ trước tiên, mọi thứ khác tính sau."),
            ["radio.khai.c6m10.1"] = ("The dam, the base, the monster. In that order. Hold.", "Con đập, căn cứ, con quái vật. Theo đúng thứ tự đó. Trụ vững."),
            ["radio.khai.c6m10.2"] = ("The dam holds. Act two is done, Brigade.", "Con đập trụ vững. Hồi thứ hai khép lại rồi, Lữ đoàn."),
            ["radio.khai.c6m10.s1"] = ("The crest first. Whoever holds the dam holds the valley.", "Mặt đập trước. Ai giữ con đập thì giữ cả thung lũng."),
            ["radio.khai.c7m03.1"] = ("The radar is our eyes. Keep them open.", "Radar là mắt của ta. Giữ cho mắt mở."),
            ["radio.khai.c7m05.3"] = ("It ran. Next time, it will not get the chance.", "Nó chạy rồi. Lần sau, nó sẽ không có cơ hội đó."),
            ["radio.khai.c7m10.1"] = ("The last air base on the coast. Take it and the sky is ours.", "Căn cứ không quân cuối cùng trên dải duyên hải. Chiếm nó là bầu trời thuộc về ta."),
            ["radio.khai.c7m10.2"] = ("Skyhold has fallen. The sky belongs to the Alliance.", "Tầng Mây đã thất thủ. Bầu trời thuộc về Liên minh."),
            ["radio.khai.c7m10.s1"] = ("The radars first. Blind, he cannot direct his wing.", "Radar trước. Mù rồi, hắn không chỉ huy được phi đội."),
            ["radio.khai.c7m10.s6"] = ("The garrison is making its last push. Hold the base.", "Quân đồn trú đang dốc sức lần cuối. Giữ lấy căn cứ."),
            ["radio.khai.c8m01.2"] = ("It is not your city. Move in.", "Đây không phải thành phố của hắn. Tiến vào."),
            ["radio.khai.c8m03.1"] = ("The city is fighting for itself. We fight with it.", "Thành phố đang tự chiến đấu. Ta chiến đấu cùng nó."),
            ["radio.khai.c8m04.1"] = ("People live in those towers. They stand.", "Có người sống trong những tòa tháp đó. Chúng phải đứng vững."),
            ["radio.khai.c8m05.2"] = ("Everything on the train.", "Dồn hết vào đoàn tàu."),
            ["radio.khai.c8m06.1"] = ("Four minutes on the square. Nobody takes it back.", "Bốn phút trên quảng trường. Không ai được giành lại."),
            ["radio.khai.c8m08.1"] = ("Nobody stays in the palace tonight. Hold the square till the last truck leaves.", "Đêm nay không ai ở lại cung điện. Giữ quảng trường cho tới khi xe cuối cùng rời đi."),
            ["radio.khai.c8m10.1"] = ("The capital, Brigade. Together with the Northern Army.", "Thủ đô, Lữ đoàn. Cùng Tập đoàn quân Phương Bắc."),
            ["radio.khai.c8m10.2"] = ("The capital is free, and the traitor's base is ash. Aurel ran south. We follow.", "Thủ đô đã tự do, căn cứ của kẻ phản bội thành tro. Aurel chạy về phía nam. Ta đuổi theo."),
            ["radio.khai.c8m10.s4"] = ("Hùng has turned! Hold the square, Brigade. Hold.", "Hùng trở mặt rồi! Giữ quảng trường, Lữ đoàn. Trụ vững."),
            ["radio.khai.c8m10.s5"] = ("His base is marked. Now we strike back.", "Căn cứ của hắn đã được đánh dấu. Giờ ta phản đòn."),
            ["radio.khai.c9m09.1"] = ("Hold the refinery. Tomorrow we finish this.", "Giữ nhà máy lọc dầu. Ngày mai ta kết thúc chuyện này."),
            ["radio.khai.c9m10.1"] = ("This is it, Brigade. Everything we have, one more time.", "Là lúc này đây, Lữ đoàn. Tất cả những gì ta có, thêm một lần nữa."),
            ["radio.khai.c9m10.2"] = ("It is over. Brigade, stand down. We go home.", "Kết thúc rồi. Lữ đoàn, nghỉ. Ta về nhà."),
            ["radio.khai.c9m10.s1"] = ("The propellant farm first. Then we choose.", "Khu nhiên liệu đẩy trước. Rồi ta sẽ chọn."),
            ["radio.khai.gen.boss.2"] = ("There it is. Everything on it.", "Nó đây rồi. Dồn hết vào nó."),
            ["radio.khai.gen.bossHalf.1"] = ("It is burning. Keep hitting it.", "Nó đang cháy. Tiếp tục nện."),
            ["radio.khai.gen.capture.1"] = ("Objective taken. Dig in.", "Đã chiếm cứ điểm. Bám trụ."),
            ["radio.khai.gen.capture.2"] = ("Good. That one is ours now.", "Tốt. Chỗ đó là của ta rồi."),
            ["radio.khai.gen.capture.3"] = ("Point secured. Keep moving.", "Cứ điểm đã an toàn. Tiếp tục tiến."),
            ["radio.khai.gen.hqHalf.2"] = ("They are on the HQ. Bring the army home.", "Chúng đang đánh vào sở chỉ huy. Kéo quân về."),
            ["radio.khai.gen.lose.1"] = ("Pull back. We regroup and go again.", "Rút về. Tập hợp lại rồi đánh tiếp."),
            ["radio.khai.gen.lost.1"] = ("We have lost a point. Take it back.", "Ta mất một cứ điểm. Chiếm lại ngay."),
            ["radio.khai.gen.stage.1"] = ("Next objective. Move.", "Mục tiêu tiếp theo. Di chuyển."),
            ["radio.khai.gen.win.1"] = ("Well done, Brigade. Rest while you can.", "Làm tốt lắm, Lữ đoàn. Nghỉ được lúc nào thì nghỉ."),
            ["radio.khai.gen.win.2"] = ("That is how it is done.", "Đánh là phải thế."),
            ["radio.khai.c4m11.3"] = ("It is coming in close. Tanks on the pier heads, now.", "Nó đang áp sát. Đưa xe tăng ra đầu cầu tàu, ngay."),
            ["radio.khai.c4m11.4"] = ("Kessler's timetable ends here.", "Thời gian biểu của Kessler kết thúc ở đây."),
            ["radio.linh.c1m02.1"] = ("The radar is on the bluffs. Its crew changes shift every hour; we will not get a better window.", "Radar nằm trên vách đá. Kíp trực đổi ca mỗi giờ; ta sẽ không có cơ hội nào tốt hơn đâu."),
            ["radio.linh.c1m03.2"] = ("The crossroads is ours. Every road inland runs through here now.", "Ngã tư là của ta. Giờ mọi con đường vào nội địa đều đi qua đây."),
            ["radio.linh.c1m06.2"] = ("Raiders on the north road. They are after the trucks, not you.", "Quân đột kích trên đường phía bắc. Chúng nhắm vào xe tải, không phải các anh."),
            ["radio.linh.c1m08.2"] = ("They have retaken a depot. They want that fuel badly.", "Chúng chiếm lại một kho rồi. Chúng thèm chỗ nhiên liệu đó lắm."),
            ["radio.linh.c1s1.1"] = ("Three farms, three looks. Nobody fights unless they must.", "Ba trang trại, ba lần nhìn. Không ai đánh nhau trừ khi bắt buộc."),
            ["radio.linh.c1s2.1"] = ("Three marked targets. They move between shots; so should we.", "Ba mục tiêu được đánh dấu. Chúng di chuyển giữa các loạt bắn; ta cũng nên thế."),
            ["radio.linh.c2m02.1"] = ("Varga's own tanks at the oasis. He is here, Colonel. In person.", "Xe tăng của chính Varga ở ốc đảo. Hắn ở đây, đại tá. Đích thân."),
            ["radio.linh.c2m06.1"] = ("Three batteries, marked. They move; we move faster.", "Ba khẩu đội, đã đánh dấu. Chúng di chuyển; ta di chuyển nhanh hơn."),
            ["radio.linh.c2m07.2"] = ("The garrison's HQ is taking fire. Hurry.", "Sở chỉ huy của đồn đang trúng đạn. Nhanh lên."),
            ["radio.linh.c2s1.1"] = ("Three looks. Their mines are the target, not their tanks.", "Ba lần nhìn. Mìn của chúng là mục tiêu, không phải xe tăng."),
            ["radio.linh.c3m02.1"] = ("Heavy tank and SAMs round the radar. Orlov guards his eyes.", "Xe tăng hạng nặng và tên lửa phòng không quanh radar. Orlov canh mắt của hắn kỹ lắm."),
            ["radio.linh.c3m06.1"] = ("Three batteries. They shoot, they move, they shoot. Be quicker than the second shot.", "Ba khẩu đội. Chúng bắn, chúng chạy, chúng lại bắn. Phải nhanh hơn loạt thứ hai."),
            ["radio.linh.c3s1.1"] = ("Look and leave. The fog helps both sides.", "Nhìn rồi rút. Sương mù giúp cả hai bên đấy."),
            ["radio.linh.c3s2.1"] = ("The wounded cannot wait for daylight. Neither can we.", "Thương binh không đợi được tới sáng. Ta cũng thế."),
            ["radio.linh.c4m02.1"] = ("Three objectives, all dug in. Take the factories first and build there.", "Ba cứ điểm, cứ điểm nào cũng cố thủ. Chiếm khu nhà máy trước rồi dựng tiền đồn ở đó."),
            ["radio.linh.c4m04.1"] = ("Three looks. Count the wagons if you can.", "Ba lần quan sát. Đếm được toa tàu thì càng tốt."),
            ["radio.linh.c4m06.1"] = ("The supergun is on the east rails. Watch the ground: where it cracks red, a shell lands three seconds later.", "Siêu pháo nằm trên đường ray phía đông. Để ý mặt đất: chỗ nào nứt đỏ, ba giây sau đạn rơi xuống đó."),
            ["radio.linh.c4m08.1"] = ("Three marked vehicles, moving slowly. Where they have been, drive carefully.", "Ba xe được đánh dấu, đi chậm. Đường chúng đã qua, lái cẩn thận."),
            ["radio.linh.c4s1.1"] = ("The prisoners are at the scrapyard. Bring them home.", "Tù binh đang ở bãi phế liệu. Đưa họ về nhà."),
            ["radio.linh.c4s2.1"] = ("Two command cars, marked. They talk a lot; that is how I found them.", "Hai xe chỉ huy, đã đánh dấu. Chúng nói nhiều lắm; tôi tìm ra chúng là nhờ thế."),
            ["radio.linh.c5m01.2"] = ("That was Dr Sen, on an open channel. She wanted us to hear.", "Đó là tiến sĩ Sen, trên kênh mở. Bà ấy muốn ta nghe thấy."),
            ["radio.linh.c5m02.1"] = ("Three launch trucks. Kill the trucks and the swarms stop coming.", "Ba xe phóng. Diệt được xe là bầy drone thôi kéo tới."),
            ["radio.linh.c5m08.1"] = ("These drones are not Sen's launch codes. Aurel is running them himself.", "Những drone này không dùng mã phóng của Sen. Aurel đang tự điều khiển chúng."),
            ["radio.linh.c5s1.1"] = ("Look for anything painted orange.", "Tìm bất cứ thứ gì sơn màu cam."),
            ["radio.linh.c5s2.1"] = ("They held for two years. Their HQ cannot hold much longer.", "Họ giữ được hai năm. Sở chỉ huy của họ không trụ được lâu nữa đâu."),
            ["radio.linh.c6m02.2"] = ("Half the trucks are out. Varga is pushing harder.", "Một nửa số xe đã thoát. Varga đang dồn ép mạnh hơn."),
            ["radio.linh.c6m04.1"] = ("Varga's scouts are at the power station already.", "Trinh sát của Varga đã tới trạm phát điện rồi."),
            ["radio.linh.c6m08.1"] = ("Seismic contact under the valley, moving west. That is Sâu Đất.", "Tín hiệu địa chấn dưới thung lũng, đang di chuyển về phía tây. Đó là Sâu Đất."),
            ["radio.linh.c6s2.1"] = ("Three looks for the engineers. Quickly, Varga is not far.", "Ba lần quan sát cho công binh. Nhanh lên, Varga không ở xa đâu."),
            ["radio.linh.c7m02.1"] = ("Look at the hangars. All of them.", "Nhìn các nhà chứa máy bay. Tất cả."),
            ["radio.linh.c7s2.1"] = ("Three places. Look for a parachute.", "Ba nơi. Tìm một chiếc dù."),
            ["radio.linh.c8m02.1"] = ("Three looks. And note anyone else who is looking too.", "Ba lần quan sát. Và ghi lại bất cứ ai khác cũng đang quan sát."),
            ["radio.linh.c8m05.1"] = ("The train is on the northern line. Sixty seconds once it stops.", "Đoàn tàu đang trên tuyến phía bắc. Nó dừng là còn sáu mươi giây."),
            ["radio.linh.c8m07.1"] = ("Three command cars. Without them, the garrison breaks.", "Ba xe chỉ huy. Mất chúng, quân đồn trú sẽ vỡ."),
            ["radio.linh.c8s1.1"] = ("This one stays off the record, Colonel.", "Chuyện này không ghi vào hồ sơ, đại tá."),
            ["radio.linh.c9m07.1"] = ("Three trucks. Every one of them counts.", "Ba xe tải. Chiếc nào cũng quan trọng."),
            ["radio.linh.c9m08.1"] = ("Four radars. The storm hides you as much as them.", "Bốn trạm radar. Bão cát che các anh cũng như che chúng."),
            ["radio.linh.c9m10.s5"] = ("The launch countdown has started. Everything Aurel has left is coming at us. Hold!", "Đếm ngược phóng đã bắt đầu. Mọi thứ Aurel còn lại đang dồn vào ta. Trụ vững!"),
            ["radio.linh.gen.boss.1"] = ("Large contact. That is the boss: focus fire.", "Mục tiêu cỡ lớn. Đó là trùm: tập trung hỏa lực."),
            ["radio.linh.gen.lost.2"] = ("Enemy flag on one of our objectives.", "Cờ địch đã cắm trên một cứ điểm của ta."),
            ["radio.linh.gen.reinforce.1"] = ("Enemy reinforcements dropping at their camp.", "Viện binh địch đang nhảy dù xuống trại của chúng."),
            ["radio.linh.gen.reinforce.2"] = ("More of them coming in by air.", "Thêm quân địch đang được thả xuống."),
            ["radio.linh.c4m11.1"] = ("Leviathan is on the far lane. We cannot see its fleet from the beach: the lighthouse can.", "Leviathan đang ở tuyến xa. Từ bãi biển ta không thấy hạm đội của nó: ngọn hải đăng thì thấy."),
            ["radio.mai.c1m04.1"] = ("Give me that crossroads and a few minutes of quiet, Colonel, and I will give you a base.", "Cho tôi cái ngã tư đó và vài phút yên tĩnh, đại tá, tôi sẽ trả lại ông một căn cứ."),
            ["radio.mai.c1m04.2"] = ("Ground is ours. Towers coming down, keep them off my crews!", "Đất là của ta rồi. Tháp đang thả xuống, đừng để chúng đụng vào người của tôi!"),
            ["radio.mai.c1m04.3"] = ("It holds. Welcome to your new HQ, Colonel. The coffee is terrible.", "Trụ được rồi. Chào mừng tới sở chỉ huy mới, đại tá. Cà phê dở tệ."),
            ["radio.mai.c1m07.2"] = ("Storm is getting worse. So is their aim, lucky for us.", "Bão càng lúc càng to. Bắn của chúng cũng càng tệ, may cho mình."),
            ["radio.mai.c1m10.s3"] = ("That is the Bastion. Early model: thin rear plates. Hit it from behind!", "Đó là Bastion. Mẫu đời đầu: giáp sau mỏng. Đánh từ phía sau!"),
            ["radio.mai.c2m05.2"] = ("Rear plates, Colonel. I know, because I put them there.", "Giáp sau, đại tá. Tôi biết, vì chính tôi lắp chúng."),
            ["radio.mai.c2m05.3"] = ("It is slowing. The engine block is exposed!", "Nó chậm lại rồi. Khối động cơ lộ ra rồi!"),
            ["radio.mai.c3m04.1"] = ("The ice holds towers. I checked. Mostly.", "Băng chịu được tháp. Tôi kiểm tra rồi. Gần như chắc chắn."),
            ["radio.mai.c3m08.1"] = ("They patched it. Badly. The rear plates are still mine.", "Chúng vá lại nó rồi. Vá ẩu. Giáp sau vẫn là của tôi."),
            ["radio.mai.c4m06.2"] = ("Take out its targeting station and its shells go wide.", "Phá trạm chỉ thị mục tiêu của nó là đạn sẽ rơi lệch."),
            ["radio.mai.c5m04.1"] = ("Forty megawatts under our feet. Give me the plant.", "Bốn mươi mê-ga-oát ngay dưới chân. Cho tôi nhà máy đó."),
            ["radio.mai.c6m03.1"] = ("She runs, Colonel. Slowly, loudly, but she runs. Keep her in one piece.", "Nó chạy rồi, đại tá. Chậm, ồn, nhưng chạy được. Giữ cho nó nguyên vẹn."),
            ["radio.mai.c6m03.3"] = ("She made it. I may cry. Do not tell anyone.", "Nó tới nơi rồi. Chắc tôi khóc mất. Đừng kể với ai nhé."),
            ["radio.mai.c6m08.2"] = ("Hit it when it surfaces. The drill head is armour; the back is not.", "Đánh nó khi nó trồi lên. Đầu khoan là giáp; phía sau thì không."),
            ["radio.mai.gen.bossHalf.2"] = ("Half its plates are gone. Aim for the seams!", "Nửa lớp giáp của nó bay rồi. Nhắm vào đường hàn!"),
            ["radio.mai.gen.hqHalf.1"] = ("HQ at half strength! I can't patch it that fast!", "Sở chỉ huy còn một nửa! Tôi vá không kịp đâu!"),
            ["radio.mai.c4m11.2"] = ("Its sides will stop anything we have. Its deck will not: artillery and bombs.", "Hông tàu chặn được mọi thứ ta có. Boong thì không: pháo binh và bom."),
            ["radio.orlov.c3m01.1"] = ("Welcome to the highlands, Colonel. You are a coordinate now.", "Chào mừng tới cao nguyên, đại tá. Giờ ngươi chỉ là một tọa độ."),
            ["radio.orlov.c3m04.2"] = ("A base on a lake. How poetic. How flammable.", "Căn cứ trên mặt hồ. Thật nên thơ. Thật dễ cháy."),
            ["radio.orlov.c3m05.2"] = ("Look up, Colonel. The coordinate has arrived.", "Nhìn lên đi, đại tá. Tọa độ đã tới."),
            ["radio.orlov.c3m06.2"] = ("You found my guns. Remarkable. Also irrelevant.", "Ngươi tìm ra pháo của ta. Đáng nể. Nhưng cũng chẳng để làm gì."),
            ["radio.orlov.c3m09.1"] = ("Fire mission. Grid one-seven. All batteries.", "Nhiệm vụ bắn. Ô lưới một-bảy. Toàn bộ khẩu đội."),
            ["radio.orlov.c3m09.2"] = ("Recalculating. Withdraw the batteries to the next line.", "Tính lại. Rút các khẩu đội về tuyến sau."),
            ["radio.orlov.c3m10.s4"] = ("The Ice Fortress will hold the gate. It always has.", "Pháo Đài Băng sẽ giữ cổng. Xưa nay vẫn thế."),
            ["radio.orlov.c3m10.s5"] = ("All batteries, the gate. Bury them in it.", "Toàn bộ khẩu đội, nhắm cổng. Chôn chúng ở đó."),
            ["radio.orlov.c9m04.1"] = ("Fire mission. The last one. All batteries.", "Nhiệm vụ bắn. Lần cuối. Toàn bộ khẩu đội."),
            ["radio.orlov.c9m04.2"] = ("Cease fire. …Cease fire.", "Ngừng bắn. …Ngừng bắn."),
            ["radio.orlov.defeat"] = ("Recalculating. Withdraw the batteries to the next line.", "Tính lại. Rút các khẩu đội về tuyến sau."),
            ["radio.orlov.taunt.1"] = ("You are a coordinate, nothing more.", "Ngươi chỉ là một tọa độ, không hơn."),
            ["radio.orlov.taunt.2"] = ("Fire mission. Grid one-seven. All batteries.", "Nhiệm vụ bắn. Ô lưới một-bảy. Toàn bộ khẩu đội."),
            ["radio.orlov.taunt.3"] = ("Patience, Colonel. The snow is on my side.", "Kiên nhẫn đi, đại tá. Tuyết đứng về phía ta."),
            ["radio.quaden.c7m01.1"] = ("Diều Hâu! Still flying that museum piece?", "Diều Hâu! Vẫn lái cái đồ cổ đó à?"),
            ["radio.quaden.c7m07.1"] = ("Look up, Colonel. That is where you lose.", "Nhìn lên đi, đại tá. Ông sẽ thua ở trên đó."),
            ["radio.quaden.c7m09.1"] = ("The sky is mine. You can keep the mud.", "Bầu trời là của ta. Bùn đất thì cứ giữ lấy."),
            ["radio.quaden.c7m09.2"] = ("Eject, eject! …Not like this.", "Nhảy dù, nhảy dù! …Không phải thế này chứ."),
            ["radio.quaden.c7m10.s3"] = ("The airship sees everything, Colonel. Everything.", "Khinh hạm nhìn thấy mọi thứ, đại tá. Mọi thứ."),
            ["radio.quaden.c9m06.1"] = ("One more time, Diều Hâu. For the old days.", "Thêm một lần nữa, Diều Hâu. Vì ngày xưa."),
            ["radio.quaden.defeat"] = ("Eject, eject! …Not like this.", "Nhảy dù, nhảy dù! …Không phải thế này chứ."),
            ["radio.quaden.taunt.1"] = ("Diều Hâu! Still flying that museum piece?", "Diều Hâu! Vẫn lái cái đồ cổ đó à?"),
            ["radio.quaden.taunt.2"] = ("Look up, Colonel. That is where you lose.", "Nhìn lên đi, đại tá. Ông sẽ thua ở trên đó."),
            ["radio.quaden.taunt.3"] = ("The sky is mine. You can keep the mud.", "Bầu trời là của ta. Bùn đất thì cứ giữ lấy."),
            ["radio.sen.c5m01.1"] = ("The swarm does not hate you, Colonel. It does not anything.", "Bầy drone không ghét các anh, đại tá. Nó chẳng có cảm xúc gì cả."),
            ["radio.sen.c5m04.2"] = ("You are sitting on a volcano, Engineer. I would not get comfortable.", "Cô đang ngồi trên núi lửa đấy, kỹ sư. Tôi mà là cô thì không ngồi yên đâu."),
            ["radio.sen.c5m05.1"] = ("Seven hundred drones in the air. Count them if you like.", "Bảy trăm drone đang trên trời. Các anh cứ đếm nếu thích."),
            ["radio.sen.c5m05.3"] = ("Enough. Stand the swarm down.", "Đủ rồi. Cho bầy drone hạ cánh."),
            ["radio.sen.c5m09.1"] = ("I designed this to save people. Remember that when it kills you.", "Tôi thiết kế thứ này để cứu người. Hãy nhớ điều đó khi nó giết các anh."),
            ["radio.sen.c5m09.2"] = ("Enough.", "Đủ rồi."),
            ["radio.sen.c5m10.end"] = ("Colonel. This is Sen. I am coming out. Do not shoot.", "Đại tá. Sen đây. Tôi đang đi ra. Đừng bắn."),
            ["radio.sen.c5m10.s3"] = ("Aurel has taken the swarm from me. I cannot stop it. Survive it.", "Aurel đã lấy bầy drone khỏi tay tôi. Tôi không dừng nó được. Hãy trụ vững."),
            ["radio.sen.c7m05.1"] = ("The shield regenerates. Keep up the fire, do not let it rest.", "Khiên của nó tự hồi phục. Cứ bắn liên tục, đừng để nó nghỉ."),
            ["radio.sen.c7s1.1"] = ("The coils in those trucks are irreplaceable. Stop them.", "Những cuộn dây trên các xe đó không thể thay thế được. Chặn chúng lại."),
            ["radio.sen.c9m05.1"] = ("That is the one from Skyhold. They have fixed the shield. Keep hitting it.", "Chính là chiếc ở Tầng Mây. Chúng đã sửa khiên. Cứ tiếp tục nện."),
            ["radio.sen.c9m10.s6"] = ("That is 01, complete. Its shield has a second layer. Do not stop firing, not for a second.", "Đó là chiếc 01, hoàn chỉnh. Khiên của nó có hai lớp. Đừng ngừng bắn, dù một giây."),
            ["radio.sen.c9s1.1"] = ("I built half of what you will see. Look closely.", "Một nửa những gì các anh sắp thấy là do tôi chế tạo. Nhìn cho kỹ."),
            ["radio.sen.defeat"] = ("Enough. Stand the swarm down.", "Đủ rồi. Cho bầy drone hạ cánh."),
            ["radio.sen.taunt.1"] = ("The swarm does not hate you. It does not anything.", "Bầy drone không ghét các anh. Nó chẳng có cảm xúc gì cả."),
            ["radio.sen.taunt.2"] = ("Seven hundred drones in the air. Count them if you like.", "Bảy trăm drone đang trên trời. Các anh cứ đếm nếu thích."),
            ["radio.sen.taunt.3"] = ("I designed this to save people. Remember that when it kills you.", "Tôi thiết kế thứ này để cứu người. Hãy nhớ điều đó khi nó giết các anh."),
            ["radio.varga.c2m01.2"] = ("Who is burning my oil? Find them. Crush them.", "Kẻ nào đang đốt dầu của ta? Tìm ra. Nghiền nát."),
            ["radio.varga.c2m02.2"] = ("Take the sand if you like. The sand does not care.", "Lấy cát nếu thích. Cát chẳng quan tâm đâu."),
            ["radio.varga.c2m04.2"] = ("My pipeline! You will pay by the barrel.", "Đường ống của ta! Ngươi sẽ trả giá theo từng thùng."),
            ["radio.varga.c2m05.1"] = ("Colonel Khải. Meet the Behemoth. It does not negotiate either.", "Đại tá Khải. Chào Behemoth đi. Nó cũng không biết thương lượng đâu."),
            ["radio.varga.c2m05.4"] = ("Retreat. Save the machines. The men can walk.", "Rút. Giữ lấy máy móc. Người thì đi bộ cũng được."),
            ["radio.varga.c2m08.2"] = ("Burn them out of my refinery!", "Đốt chúng ra khỏi nhà máy của ta!"),
            ["radio.varga.c2m09.1"] = ("Steel does not negotiate, Colonel.", "Thép không biết thương lượng, đại tá ạ."),
            ["radio.varga.c2m09.3"] = ("Retreat. Save the machines.", "Rút. Giữ lấy máy móc."),
            ["radio.varga.c2m10.s5"] = ("You want fire, Colonel? Here is fire.", "Muốn lửa hả, đại tá? Lửa đây."),
            ["radio.varga.c2m10.s6"] = ("Every tank I have left, to the refinery. Now!", "Toàn bộ xe tăng còn lại, tới nhà máy lọc dầu. Ngay!"),
            ["radio.varga.c3m08.2"] = ("I fixed her, Colonel. I always fix her.", "Ta đã sửa lại nó, đại tá. Ta luôn sửa được nó."),
            ["radio.varga.c6m01.1"] = ("You took my fortress. I have come to collect it.", "Ngươi lấy pháo đài của ta. Ta tới lấy lại đây."),
            ["radio.varga.c6m03.2"] = ("That is MY machine! Burn it!", "Đó là cỗ máy của TA! Đốt nó đi!"),
            ["radio.varga.c6m09.1"] = ("Every tank you burn, I build two.", "Ngươi đốt một chiếc, ta đóng hai chiếc."),
            ["radio.varga.c6m09.2"] = ("Fall back to the dam. The Frost Monster will finish this.", "Rút về con đập. Quái Vật Băng sẽ kết thúc chuyện này."),
            ["radio.varga.c6m10.s3"] = ("Meet my masterpiece, Colonel.", "Chào kiệt tác của ta đi, đại tá."),
            ["radio.varga.c9m01.1"] = ("Colonel. We meet in the sand again. The last time, I think.", "Đại tá. Ta lại gặp nhau trên cát. Lần cuối, ta nghĩ vậy."),
            ["radio.varga.c9m03.1"] = ("Steel does not negotiate. But it can be tired, Colonel.", "Thép không biết thương lượng. Nhưng thép cũng biết mệt, đại tá ạ."),
            ["radio.varga.c9m03.2"] = ("Enough. Let the machines rest.", "Đủ rồi. Để những cỗ máy được nghỉ."),
            ["radio.varga.defeat"] = ("Retreat. Save the machines. The men can walk.", "Rút. Giữ lấy máy móc. Người thì đi bộ cũng được."),
            ["radio.varga.taunt.1"] = ("Steel does not negotiate, Colonel.", "Thép không biết thương lượng, đại tá ạ."),
            ["radio.varga.taunt.2"] = ("Every tank you burn, I build two.", "Ngươi đốt một chiếc, ta đóng hai chiếc."),
            ["radio.varga.taunt.3"] = ("Come closer. My guns are lonely.", "Lại gần đây. Pháo của ta đang buồn lắm."),
            ["result.fragment"] = ("New in the dossier: {0}", "Hồ sơ mới: {0}"),
