            ["stage.c9m10.propellant"] = ("Burn the Propellant", "Đốt nhiên liệu đẩy"),
            ["stage.c9m10.radars"] = ("Blind the West Radars", "Làm mù radar phía tây"),
            ["timeline.0"] = ("Two years ago: the Night of Steel. Hegemon seizes the Lam Hai coast; Director Aurel declares the \"Protectorate\".", "Hai năm trước: Đêm Thép. Hegemon chiếm dải duyên hải Lam Hải; giám đốc Aurel tuyên bố thành lập \"Chính quyền Bảo hộ\"."),
            ["timeline.1"] = ("The brigade lands at Bãi Đổ Bộ, sets up its first base in Greenvale and storms the Ashfield fortress, bringing down the Bastion.", "Lữ đoàn đổ bộ ở Bãi Đổ Bộ, dựng căn cứ đầu tiên ở Lũng Xanh rồi đánh chiếm pháo đài Đồng Tro, hạ gục Bastion."),
            ["timeline.2"] = ("Varga shows himself at Dunebreak; his Behemoth falls in a sandstorm, and the refinery burns with the Inferno inside it.", "Varga lộ mặt ở Đồi Cát; Behemoth của hắn gục trong bão cát, còn nhà máy lọc dầu bốc cháy cùng Inferno bên trong."),
            ["timeline.3"] = ("The brigade blinds Orlov's radar line, brings the Iron Bird down in the snow and breaks through at Frostpeak, past the Ice Fortress.", "Lữ đoàn làm mù tuyến radar của Orlov, bắn rơi Chim Sắt trên tuyết và chọc thủng Đỉnh Sương Giá, vượt qua Pháo Đài Băng."),
            ["timeline.4"] = ("Kessler's timetable breaks: the steel train is derailed, the rail supergun silenced, and the port taken from Tempest on its own docks.", "Thời gian biểu của Kessler đổ vỡ: tàu thép bị lật, siêu pháo đường ray câm họng, bến cảng bị chiếm từ tay Tempest ngay trên cầu tàu."),
            ["timeline.5"] = ("The Hive and its mothership fall over Ember Ridge. Dr Sen walks out of the burning drone works and gives herself up, with the Silver Bug files.", "Tổ Ong và tàu mẹ của nó rơi trên Sườn Dung Nham. Tiến sĩ Sen bước ra khỏi xưởng drone đang cháy và ra hàng, mang theo hồ sơ Bọ Bạc."),
            ["timeline.6"] = ("The counterstrike breaks on the Hydro Dam: the Frost Monster goes into the gorge and General Hùng's army arrives in time.", "Đợt tổng phản công vỡ tan trước Đập Thủy Điện: Quái Vật Băng lao xuống hẻm sông, và đạo quân của tướng Hùng tới kịp."),
            ["timeline.7"] = ("Silver Bug shows itself and runs; Quạ Đen is shot down, and Skyhold falls with his command airship.", "Bọ Bạc lộ diện rồi bỏ chạy; Quạ Đen bị bắn rơi, Tầng Mây thất thủ cùng khinh hạm chỉ huy của hắn."),
            ["timeline.8"] = ("The capital is freed, but General Hùng turns on the brigade in the middle of it. The traitor's base falls; Aurel escapes to the launch site.", "Thủ đô được giải phóng, nhưng tướng Hùng trở mặt với lữ đoàn ngay giữa trận. Căn cứ của kẻ phản bội thất thủ; Aurel chạy về bãi phóng."),
            ["timeline.9"] = ("Silver Bug falls on its own pad. Hegemon is finished, and the Lam Hai coast is free.", "Bọ Bạc rơi xuống ngay trên bệ phóng của nó. Hegemon sụp đổ, dải duyên hải Lam Hải được tự do."),
        };

